@dataclass
class ReaderComposeBuildMeta:
    cache_hit: bool
    cache_layer: str
    build_mode: str
    source_signature: str
    source_sig_hash: str
    engine_version: str = COMPOSE_ENGINE_VERSION
    iterations: int = 0
    degraded: bool = False
    stop_reason: str = "unknown"


ReaderComposeProgressCallback = Callable[[str, Dict[str, Any]], Awaitable[None]]


class LiteratureReaderComposeService:
    def __init__(self) -> None:
        self._redis_client: Any = None
        self._review_sessions: Dict[str, Dict[str, Any]] = {}
        self._reader_service = get_literature_reader_service()
        self._mm_layout_service = ReaderMultimodalLayoutService()
        self._component_contract_service = get_reader_component_contract_service()
        self._compose_agent_runtime = get_reader_compose_agent_runtime()
        self._single_agent_validator = ReaderSingleAgentValidator()
        self._single_agent_controller = ReaderSingleAgentController(
            validator=self._single_agent_validator,
            max_steps=max(1, int(getattr(settings, "reader_agent_max_steps", 12) or 12)),
            max_repair_rounds=max(0, int(getattr(settings, "reader_agent_max_repair_rounds", 2) or 2)),
        )
        self._panel_plan_agent = get_reader_panel_plan_agent_service()

    @staticmethod
    async def _emit_progress_event(
        progress_callback: Optional[ReaderComposeProgressCallback],
        *,
        event: str,
        data: Mapping[str, Any],
    ) -> None:
        if progress_callback is None:
            return
        try:
            await progress_callback(str(event or "").strip() or "stage", dict(data or {}))
        except Exception as exc:
            logger.debug(
                "[ReaderComposeService] progress callback failed event={} error={}",
                str(event or "").strip() or "stage",
                str(exc or "").strip() or type(exc).__name__,
            )

    @staticmethod
    def _safe_int(value: Any, default: int = 0) -> int:
        try:
            return int(value)
        except Exception:
            return int(default)

    @staticmethod
    def _safe_float(value: Any, default: float = 0.0) -> float:
        try:
            return float(value)
        except Exception:
            return float(default)

    def _pipeline_version(self, override: Optional[str] = None) -> str:
        token = str(override or getattr(settings, "reader_pipeline_version", SIMPLIFIED_PIPELINE_VERSION_DEFAULT) or "").strip()
        return token or SIMPLIFIED_PIPELINE_VERSION_DEFAULT

    def _use_semantic_atom_pipeline(self, pipeline_version: Optional[str] = None) -> bool:
        token = self._pipeline_version(pipeline_version).strip().lower()
        return token in {"simplified_v2", "reader_workbench_v2_phase12", "phase12_semantic_v1"}

    def _use_layout_uid_pipeline(self, pipeline_version: Optional[str] = None) -> bool:
        token = self._pipeline_version(pipeline_version).strip().lower()
        return token == LAYOUT_UID_PIPELINE_VERSION

    def _pipeline_mode(self) -> str:
        explicit = str(getattr(settings, "reader_pipeline_mode", PIPELINE_MODE_SINGLE_AGENT_V2) or "").strip().lower()
        if explicit in {PIPELINE_MODE_LEGACY, PIPELINE_MODE_SINGLE_AGENT_V2}:
            return explicit
        return PIPELINE_MODE_SINGLE_AGENT_V2

    @staticmethod
    def _parse_int_allowlist(raw: str) -> set[int]:
        values: set[int] = set()
        text = str(raw or "").strip()
        if not text:
            return values
        for part in text.split(","):
            token = part.strip()
            if not token:
                continue
            if token.isdigit():
                values.add(int(token))
        return values

    def _is_single_agent_v2_enabled(self, *, paper_id: int, page: int) -> bool:
        _ = (paper_id, page)
        return self._pipeline_mode() == PIPELINE_MODE_SINGLE_AGENT_V2

    def _cached_payload_has_meaningful_reading_flow(self, payload: Any) -> bool:
        if not isinstance(payload, dict):
            return False
        ui_plan = payload.get("ui_plan")
        if not isinstance(ui_plan, dict):
            return False
        components = ui_plan.get("components")
        if not isinstance(components, list):
            return False

        reading_flow_types = {
            "SectionHeading",
            "ParagraphProse",
            "ListBlock",
            "FigurePanel",
            "TablePanel",
            "EquationBlock",
            "AbstractCard",
            "MethodologyCard",
            "CalloutBox",
            "CompareInsightsCard",
            "InsightClusterCard",
            "SectionBridgeCard",
        }
        meaningful_count = 0
        for node in components:
            if not isinstance(node, dict):
                continue
            node_type = str(node.get("type") or "").strip()
            if node_type not in reading_flow_types:
                continue
            props = node.get("props")
            props_map = props if isinstance(props, dict) else {}
            if node_type == "FigurePanel":
                image_url = str(props_map.get("image_url") or "").strip()
                caption = str(props_map.get("caption") or "").strip()
                if image_url or caption:
                    meaningful_count += 1
                    continue
            text_hint = " ".join(
                str(props_map.get(key) or "").strip()
                for key in ("text", "title", "caption", "content", "description")
            ).strip()
            if text_hint:
                meaningful_count += 1
            if meaningful_count >= 2:
                return True
        return meaningful_count >= 2

    @staticmethod
    def _compatible_source_signature_prefix(source_signature: str) -> str:
        token = str(source_signature or "").strip()
        if not token:
            return ""
        marker = "|h:"
        index = token.rfind(marker)
        if index <= 0:
            return ""
        return token[: index + len(marker)]

    def _should_rebuild_cached_payload(self, payload: Any) -> bool:
        if not isinstance(payload, dict):
            return False
        payload_engine_version = str(payload.get("engine_version") or "").strip()
        if payload_engine_version and payload_engine_version != COMPOSE_ENGINE_VERSION:
            return True
        status_value = str(payload.get("status") or "").strip().lower()
        if status_value != "fallback":
            return False
        degraded_reason = str(payload.get("degraded_reason") or "").strip().lower()
        build_mode = str(payload.get("build_mode") or "").strip().lower()
        gate = payload.get("minimal_gate_report")
        if not isinstance(gate, dict):
            return False
        used_atom_count = self._safe_int(gate.get("used_atom_count"), 0)
        usable_atom_count = self._safe_int(gate.get("usable_atom_count"), 0)
        # Auto-heal only when cached simplified fallback clearly dropped all usable atoms.
        if usable_atom_count <= 0 or used_atom_count > 0:
            return False
        has_meaningful_reading_flow = self._cached_payload_has_meaningful_reading_flow(payload)
        if degraded_reason == "simplified_pipeline":
            return not has_meaningful_reading_flow
        if degraded_reason == "no_drop_blocks_failed_auto_fallback":
            return True
        if build_mode == "compose_agent_simplified":
            return not has_meaningful_reading_flow
        return False

    async def _delete_payload_from_redis(self, key: str) -> None:
        client = await self._get_redis_client()
        if client is None:
            return
        try:
            await client.delete(key)
        except Exception:
            return

    async def build_or_get_composed_payload(
        self,
        *,
        db: AsyncSession,
        user_id: int,
        paper: Paper,
        page: int,
        selected_kb_id: Optional[int] = None,
        pipeline_version_override: Optional[str] = None,
        force_refresh: bool = False,
        regenerate: bool = False,
        latency_budget_ms: Optional[int] = None,
        quality_target: Optional[float] = None,
        max_iterations: Optional[int] = None,
        style_intent: Optional[str] = None,
        theme_mode: Optional[str] = None,
        detail_level: Optional[str] = None,
        compare_mode: Optional[bool] = None,
        citation_tldr: Optional[bool] = None,
        publish_ready_event_enabled: bool = False,
        progress_callback: Optional[ReaderComposeProgressCallback] = None,
    ) -> Tuple[Dict[str, Any], ReaderComposeBuildMeta]:
        # 来源签名（source signature）会纳入用户可见选项和来源材料，因此即使是同一页，
        # 缓存命中也不会跨越风格、细节级别或知识库边界。
        page_num = max(1, int(page))
        parser_force_refresh = bool(force_refresh)
        compose_force_refresh = bool(force_refresh or regenerate)
        logger.info(
            "[ReaderComposeService] build_or_get_composed_payload start "
            f"paper={paper.id} page={page_num} user={user_id} "
            f"compose_force_refresh={compose_force_refresh} parser_force_refresh={parser_force_refresh} "
            f"regenerate={bool(regenerate)}"
        )
        pipeline_mode = self._pipeline_mode()
        pipeline_version = self._pipeline_version(pipeline_version_override)
        latency_budget = self._normalize_latency_budget(latency_budget_ms)
        quality_goal = self._normalize_quality_target(quality_target)
        normalized_theme = self._normalize_theme_mode(theme_mode)
        normalized_detail = self._normalize_detail_level(detail_level)
        use_compare_mode = bool(compare_mode)
        use_citation_tldr = bool(citation_tldr)
        normalized_max_iterations = self._normalize_max_iterations(max_iterations)

        source_signature = await self._build_source_signature(
            db=db,
            user_id=int(user_id),
            paper=paper,
            selected_kb_id=selected_kb_id,
            style_intent=style_intent,
            theme_mode=normalized_theme,
            detail_level=normalized_detail,
            compare_mode=use_compare_mode,
            citation_tldr=use_citation_tldr,
            max_iterations=normalized_max_iterations,
        )
        logger.info(
            "[ReaderComposeService] source signature ready "
            f"paper={paper.id} page={page_num} mode={pipeline_mode} version={pipeline_version}"
        )
        sig_hash = self._signature_hash(source_signature)
        redis_key = self._cache_key(
            user_id=int(user_id),
            paper_id=int(paper.id),
            page=page_num,
            sig_hash=sig_hash,
            pipeline_mode=pipeline_mode,
            pipeline_version=pipeline_version,
        )
        lock_key = self._lock_key(
            user_id=int(user_id),
            paper_id=int(paper.id),
            page=page_num,
            pipeline_mode=pipeline_mode,
            pipeline_version=pipeline_version,
        )

        if not compose_force_refresh:
            # 缓存 Redis 是快速路径；每次命中仍会按当前运行时契约修复后，
            # 再应用用户 overlay。
            cached_payload = await self._read_payload_from_redis(redis_key)
            if isinstance(cached_payload, dict):
                if self._should_rebuild_cached_payload(cached_payload):
                    logger.info(
                        "[ReaderComposeService] skip stale redis compose cache and rebuild "
                        f"paper={paper.id} page={page_num}"
                    )
                    await self._delete_payload_from_redis(redis_key)
                else:
                    repaired_cached_payload = self._ensure_payload_contract(page=page_num, payload=dict(cached_payload))
                    if repaired_cached_payload != cached_payload:
                        await self._write_payload_to_redis(redis_key, repaired_cached_payload)
                    payload = self._with_cache_meta(repaired_cached_payload, cache_hit=True, cache_layer="redis")
                    payload = await self._apply_overlay_for_user(
                        db=db,
                        user_id=int(user_id),
                        paper_id=int(paper.id),
                        page=page_num,
                        source_signature=source_signature,
                        payload=payload,
                    )
                    payload = self._ensure_payload_contract(page=page_num, payload=payload)
                    quality_report = payload.get("quality_report") or {}
                    return payload, ReaderComposeBuildMeta(
                        cache_hit=True,
                        cache_layer="redis",
                        build_mode=str(payload.get("build_mode") or "compose_cache"),
                        source_signature=source_signature,
                        source_sig_hash=sig_hash,
                        iterations=int(quality_report.get("iterations") or 0),
                        degraded=bool(quality_report.get("degraded")),
                        stop_reason=str(quality_report.get("stop_reason") or "cache_hit"),
                    )

            cached_row = await self._read_payload_from_db(
                db=db,
                paper_id=int(paper.id),
                page=page_num,
                source_signature=source_signature,
            )
            if isinstance(cached_row, dict):
                if self._should_rebuild_cached_payload(cached_row):
                    logger.info(
                        "[ReaderComposeService] skip stale db compose cache and rebuild "
                        f"paper={paper.id} page={page_num}"
                    )
                else:
                    await self._write_payload_to_redis(redis_key, cached_row)
                    payload = self._with_cache_meta(cached_row, cache_hit=True, cache_layer="db")
                    payload = await self._apply_overlay_for_user(
                        db=db,
                        user_id=int(user_id),
                        paper_id=int(paper.id),
                        page=page_num,
                        source_signature=source_signature,
                        payload=payload,
                    )
                    payload = self._ensure_payload_contract(page=page_num, payload=payload)
                    quality_report = payload.get("quality_report") or {}
                    return payload, ReaderComposeBuildMeta(
                        cache_hit=True,
                        cache_layer="db",
                        build_mode=str(payload.get("build_mode") or "compose_cache"),
                        source_signature=source_signature,
                        source_sig_hash=sig_hash,
                        iterations=int(quality_report.get("iterations") or 0),
                        degraded=bool(quality_report.get("degraded")),
                        stop_reason=str(quality_report.get("stop_reason") or "cache_hit"),
                    )

            compatible_cached_row = await self._read_compatible_payload_from_db(
                db=db,
                paper_id=int(paper.id),
                page=page_num,
                source_signature=source_signature,
                pipeline_version=pipeline_version,
            )
            if isinstance(compatible_cached_row, dict):
                # 只有 canonical source 前缀匹配时才复用兼容 DB 行；随后把请求的
                # 完整签名写回 payload，确保下游 overlay 仍然按用户隔离。
                logger.info(
                    "[ReaderComposeService] reuse compatible compose cache "
                    f"paper={paper.id} page={page_num} requested_sig={sig_hash} "
                    f"payload_sig={self._signature_hash(str(compatible_cached_row.get('source_signature') or ''))}"
                )
                compatible_payload = dict(compatible_cached_row)
                compatible_payload["source_signature"] = source_signature
                await self._write_payload_to_redis(redis_key, compatible_payload)
                payload = self._with_cache_meta(compatible_payload, cache_hit=True, cache_layer="db_compatible")
                payload = await self._apply_overlay_for_user(
                    db=db,
                    user_id=int(user_id),
                    paper_id=int(paper.id),
                    page=page_num,
                    source_signature=source_signature,
                    payload=payload,
                )
                payload = self._ensure_payload_contract(page=page_num, payload=payload)
                quality_report = payload.get("quality_report") or {}
                return payload, ReaderComposeBuildMeta(
                    cache_hit=True,
                    cache_layer="db_compatible",
                    build_mode=str(payload.get("build_mode") or "compose_cache"),
                    source_signature=source_signature,
                    source_sig_hash=sig_hash,
                    iterations=int(quality_report.get("iterations") or 0),
                    degraded=bool(quality_report.get("degraded")),
                    stop_reason=str(quality_report.get("stop_reason") or "compatible_cache_hit"),
                )

        async def _reuse_waited_payload(
            cached_payload: Mapping[str, Any],
            *,
            cache_layer: str,
        ) -> Tuple[Dict[str, Any], ReaderComposeBuildMeta]:
            repaired_cached_payload = self._ensure_payload_contract(page=page_num, payload=dict(cached_payload))
            if cache_layer == "redis" and repaired_cached_payload != cached_payload:
                await self._write_payload_to_redis(redis_key, repaired_cached_payload)
            payload = self._with_cache_meta(repaired_cached_payload, cache_hit=True, cache_layer=cache_layer)
            payload = await self._apply_overlay_for_user(
                db=db,
                user_id=int(user_id),
                paper_id=int(paper.id),
                page=page_num,
                source_signature=source_signature,
                payload=payload,
            )
            payload = self._ensure_payload_contract(page=page_num, payload=payload)
            quality_report = payload.get("quality_report") or {}
            return payload, ReaderComposeBuildMeta(
                cache_hit=True,
                cache_layer=cache_layer,
                build_mode=str(payload.get("build_mode") or "compose_cache"),
                source_signature=source_signature,
                source_sig_hash=sig_hash,
                iterations=int(quality_report.get("iterations") or 0),
                degraded=bool(quality_report.get("degraded")),
                stop_reason=str(quality_report.get("stop_reason") or "cache_hit"),
            )

        lock_token = await self._acquire_lock(lock_key)
        logger.info(
            "[ReaderComposeService] compose lock attempt "
            f"paper={paper.id} page={page_num} acquired={bool(lock_token)} compose_force_refresh={compose_force_refresh}"
        )
        if lock_token is None:
            # 重复构建通常比等待更昂贵；新请求会多等一会儿，给进行中的 worker
            # 写入可复用缓存的机会，而 force-refresh 保持较短的交互预算。
            waited = 0.0
            wait_limit = LOCK_WAIT_SECONDS if compose_force_refresh else LOCK_RESULT_WAIT_SECONDS
            waiting_notice_emitted = False
            while waited < wait_limit and lock_token is None:
                if not compose_force_refresh:
                    cached_payload = await self._read_payload_from_redis(redis_key)
                    if isinstance(cached_payload, dict):
                        if self._should_rebuild_cached_payload(cached_payload):
                            await self._delete_payload_from_redis(redis_key)
                        else:
                            return await _reuse_waited_payload(cached_payload, cache_layer="redis")
                    compatible_cached_row = await self._read_compatible_payload_from_db(
                        db=db,
                        paper_id=int(paper.id),
                        page=page_num,
                        source_signature=source_signature,
                        pipeline_version=pipeline_version,
                    )
                    if isinstance(compatible_cached_row, dict):
                        compatible_payload = dict(compatible_cached_row)
                        compatible_payload["source_signature"] = source_signature
                        await self._write_payload_to_redis(redis_key, compatible_payload)
                        return await _reuse_waited_payload(compatible_payload, cache_layer="db_compatible")
                    if not waiting_notice_emitted:
                        waiting_notice_emitted = True
                        await self._emit_progress_event(
                            progress_callback,
                            event="stage",
                            data={
                                "stage": "compose_wait",
                                "status": "started",
                                "label": "等待同页结果",
                                "message": "已有相同页面正在生成，等待复用结果",
                                "page": int(page_num),
                            },
                        )
                current_lock = await self._read_lock_token(lock_key)
                if current_lock is None:
                    lock_token = await self._acquire_lock(lock_key)
                    if lock_token is not None:
                        break
                await asyncio.sleep(LOCK_POLL_INTERVAL_SECONDS)
                waited += LOCK_POLL_INTERVAL_SECONDS

            if lock_token is None:
                logger.warning(
                    "[ReaderComposeService] compose lock wait timeout without duplicate rebuild "
                    f"paper={paper.id} page={page_num} waited={waited:.2f}s compose_force_refresh={compose_force_refresh}"
                )
                fallback_payload = await self._build_force_refresh_timeout_fallback_payload(
                    db=db,
                    user_id=int(user_id),
                    paper=paper,
                    page=page_num,
                    selected_kb_id=selected_kb_id,
                    style_intent=style_intent,
                    theme_mode=normalized_theme,
                    detail_level=normalized_detail,
                    compare_mode=use_compare_mode,
                    source_signature=source_signature,
                    pipeline_version=pipeline_version,
                )
                fallback_payload = self._with_cache_meta(fallback_payload, cache_hit=False, cache_layer="none")
                fallback_payload = await self._apply_overlay_for_user(
                    db=db,
                    user_id=int(user_id),
                    paper_id=int(paper.id),
                    page=page_num,
                    source_signature=source_signature,
                    payload=fallback_payload,
                )
                fallback_payload = self._ensure_payload_contract(page=page_num, payload=fallback_payload)
                quality_report = fallback_payload.get("quality_report") or {}
                return fallback_payload, ReaderComposeBuildMeta(
                    cache_hit=False,
                    cache_layer="none",
                    build_mode=str(fallback_payload.get("build_mode") or "compose_agent_simplified"),
                    source_signature=source_signature,
                    source_sig_hash=sig_hash,
                    iterations=int(quality_report.get("iterations") or 0),
                    degraded=bool(quality_report.get("degraded") or compose_force_refresh),
                    stop_reason="force_refresh_lock_timeout" if compose_force_refresh else "lock_wait_timeout",
                )

        lock_keepalive_stop: Optional[asyncio.Event] = None
        lock_keepalive_task: Optional[asyncio.Task[Any]] = None
        if lock_token is not None:
            lock_keepalive_stop = asyncio.Event()
            lock_keepalive_task = asyncio.create_task(
                self._maintain_lock(
                    lock_key=lock_key,
                    token=lock_token,
                    stop_event=lock_keepalive_stop,
                )
            )

        try:
            page_payload_started_at = time.perf_counter()
            await self._emit_progress_event(
                progress_callback,
                event="stage",
                data={
                    "stage": "page_payload",
                    "status": "started",
                    "message": "正在解析页面并准备阅读骨架",
                    "page": int(page_num),
                },
            )
            logger.info(
                "[ReaderComposeService] build base payload start "
                f"paper={paper.id} page={page_num} parser_force_refresh={bool(parser_force_refresh)}"
            )
            base_payload, _ = await self._reader_service.build_or_get_page_payload(
                db=db,
                user_id=int(user_id),
                paper=paper,
                page=page_num,
                selected_kb_id=selected_kb_id,
                force_refresh=bool(parser_force_refresh),
                style_hint=None,
                prefer_agent=False,
                publish_ready_event_enabled=False,
            )
            logger.info(
                "[ReaderComposeService] build base payload done "
                f"paper={paper.id} page={page_num}"
            )
            page_payload_elapsed_ms = int(max(0.0, (time.perf_counter() - page_payload_started_at) * 1000.0))
            await self._emit_progress_event(
                progress_callback,
                event="stage",
                data={
                    "stage": "page_payload",
                    "status": "done",
                    "message": "阅读骨架已准备",
                    "page": int(page_num),
                    "elapsed_ms": page_payload_elapsed_ms,
                },
            )
            initial_ui_plan = self._build_initial_ui_plan(
                paper=paper,
                page=page_num,
                base_payload=dict(base_payload or {}),
                style_intent=style_intent,
                theme_mode=normalized_theme,
                detail_level=normalized_detail,
                compare_mode=use_compare_mode,
            )
            if list((initial_ui_plan or {}).get("components") or []):
                await self._emit_progress_event(
                    progress_callback,
                    event="plan_draft",
                    data={
                        "iteration": 0,
                        "ui_plan": initial_ui_plan,
                        "phase": "skeleton",
                        "layout_lock": True,
                    },
                )
            simplified_enabled = self._is_single_agent_v2_enabled(
                paper_id=int(paper.id),
                page=page_num,
            )
            if simplified_enabled:
                compose_started_at = time.perf_counter()
                await self._emit_progress_event(
                    progress_callback,
                    event="stage",
                    data={
                        "stage": "compose_pipeline",
                        "status": "started",
                        "message": "正在组织阅读流",
                        "page": int(page_num),
                    },
                )
                logger.info(
                    "[ReaderComposeService] single_agent_v2 pipeline start "
                    f"paper={paper.id} page={page_num}"
                )
                use_layout_uid_pipeline = self._use_layout_uid_pipeline(pipeline_version)
                use_semantic_atom_pipeline = self._use_semantic_atom_pipeline(pipeline_version)
                if use_layout_uid_pipeline:
                    primary_builder = self._build_layout_uid_pipeline_result
                    fallback_builder = self._build_single_agent_v2_result
                    primary_label = "layout_uid_pipeline"
                    fallback_label = "single_agent_v2_controller"
                else:
                    primary_builder = (
                        self._build_simplified_pipeline_result
                        if use_semantic_atom_pipeline
                        else self._build_single_agent_v2_result
                    )
                    fallback_builder = (
                        self._build_single_agent_v2_result
                        if use_semantic_atom_pipeline
                        else self._build_simplified_pipeline_result
                    )
                    primary_label = "semantic_atom_pipeline" if use_semantic_atom_pipeline else "single_agent_v2_controller"
                    fallback_label = "single_agent_v2_controller" if use_semantic_atom_pipeline else "semantic_atom_pipeline"
                try:
                    simplified_result = await primary_builder(
                        db=db,
                        user_id=int(user_id),
                        paper=paper,
                        page=page_num,
                        base_payload=base_payload,
                        style_intent=style_intent,
                        theme_mode=normalized_theme,
                        detail_level=normalized_detail,
                        compare_mode=use_compare_mode,
                        latency_budget_ms=latency_budget,
                        selected_kb_id=selected_kb_id,
                        pipeline_version=pipeline_version,
                        progress_callback=progress_callback,
                    )
                except Exception as exc:
                    logger.exception(
                        f"[ReaderComposeService] {primary_label} failed; fallback to {fallback_label} "
                        f"paper={paper.id} page={page_num}: {exc}"
                    )
                    simplified_result = await fallback_builder(
                        db=db,
                        user_id=int(user_id),
                        paper=paper,
                        page=page_num,
                        base_payload=base_payload,
                        style_intent=style_intent,
                        theme_mode=normalized_theme,
                        detail_level=normalized_detail,
                        compare_mode=use_compare_mode,
                        latency_budget_ms=latency_budget,
                        selected_kb_id=selected_kb_id,
                        pipeline_version=pipeline_version,
                        progress_callback=progress_callback,
                    )
                base_payload = dict(simplified_result.get("base_payload") or base_payload)
                loop_result = dict(simplified_result.get("loop_result") or {})
                assets = list(simplified_result.get("assets") or [])
                compose_elapsed_ms = int(max(0.0, (time.perf_counter() - compose_started_at) * 1000.0))
                await self._emit_progress_event(
                    progress_callback,
                    event="stage",
                    data={
                        "stage": "compose_pipeline",
                        "status": "done",
                        "message": "阅读流组织完成",
                        "page": int(page_num),
                        "elapsed_ms": compose_elapsed_ms,
                    },
                )
                logger.info(
                    "[ReaderComposeService] single_agent_v2 pipeline done "
                    f"paper={paper.id} page={page_num} build_mode={str(loop_result.get('build_mode') or '')}"
                )
            else:
                base_payload = await self._apply_multimodal_layout_assist(
                    paper=paper,
                    page=page_num,
                    base_payload=base_payload,
                )
                takeaways = await self._build_takeaways_with_neighbor_context(
                    db=db,
                    user_id=int(user_id),
                    paper=paper,
                    page=page_num,
                    selected_kb_id=selected_kb_id,
                    current_payload=base_payload,
                    detail_level=normalized_detail,
                )
                if takeaways:
                    base_payload = dict(base_payload)
                    base_payload["takeaways"] = takeaways

                loop_result = await self.run_react_compose_loop(
                    paper=paper,
                    page=page_num,
                    base_payload=base_payload,
                    style_intent=style_intent,
                    theme_mode=normalized_theme,
                    detail_level=normalized_detail,
                    compare_mode=use_compare_mode,
                    quality_target=quality_goal,
                    latency_budget_ms=latency_budget,
                    max_iterations=normalized_max_iterations,
                )
                assets = await self.collect_assets_with_policy(
                    paper=paper,
                    page=page_num,
                    base_payload=base_payload,
                    ui_plan=loop_result.get("ui_plan") or {},
                    citation_tldr=use_citation_tldr,
                )

            quality_report = dict(loop_result.get("quality_report") or {})
            quality_report["iterations"] = int(loop_result.get("iterations") or 0)
            quality_report["degraded"] = bool(loop_result.get("degraded"))
            quality_report["stop_reason"] = str(loop_result.get("stop_reason") or "unknown")
            quality_report["quality_target"] = quality_goal
            quality_report["latency_budget_ms"] = latency_budget
            validation_report = self._build_validation_report(
                quality_report=quality_report,
                minimal_gate_report=dict(base_payload.get("minimal_gate_report") or {}),
            )
            main_block_ids, aux_block_ids = self._partition_main_aux_block_ids(
                page=page_num,
                base_payload=base_payload,
                ui_plan=dict(loop_result.get("ui_plan") or {}),
            )
            status_value = "done" if bool(validation_report.get("passed")) else "fallback"
            degraded_reason = ""
            if status_value != "done":
                degraded_reason = str(quality_report.get("stop_reason") or "validator_non_converged").strip()
                if not degraded_reason or degraded_reason == "unknown":
                    degraded_reason = "validator_non_converged"

            payload: Dict[str, Any] = {
                "paper_id": int(paper.id),
                "page": page_num,
                "status": status_value,
                "degraded_reason": degraded_reason,
                "pipeline_version": pipeline_version,
                "engine_version": COMPOSE_ENGINE_VERSION,
                "source_signature": source_signature,
                "build_mode": str(loop_result.get("build_mode") or "compose_agent"),
                "ui_plan": dict(loop_result.get("ui_plan") or {}),
                "assets": assets,
                "grounding_mode": str(base_payload.get("grounding_mode") or ""),
                "evidence_enabled": base_payload.get("evidence_enabled"),
                "runtime_build_plan_evidence": base_payload.get("runtime_build_plan_evidence"),
                "page_grounding_policy": dict(base_payload.get("page_grounding_policy") or {}),
                "scheme_choice": dict(base_payload.get("scheme_choice") or (((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("scheme_choice") or {})),
                "decision_log": list(base_payload.get("decision_log") or (((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("decision_log") or [])),
                "omission_decisions": list(base_payload.get("omission_decisions") or (((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("omission_decisions") or [])),
                "quality_report": quality_report,
                "iteration_trace": list(loop_result.get("iteration_trace") or []),
                "main_block_ids": main_block_ids,
                "aux_block_ids": aux_block_ids,
                "validation_report": validation_report,
                "asset_policy": {
                    "pdf_first": True,
                    "web_fallback": bool(getattr(settings, "reader_external_image_enabled", False)),
                    "max_external_images": 2,
                    "version": COMPOSE_ASSET_POLICY_VERSION,
                },
                "layout_channels": dict(base_payload.get("layout_channels") or {}),
                "mm_assist_meta": dict(base_payload.get("mm_assist_meta") or {}),
                "parser_chain_meta": dict(base_payload.get("parser_chain_meta") or {}),
                "docmind_meta": dict(base_payload.get("docmind_meta") or {}),
                "docmind_structure": dict(base_payload.get("docmind_structure") or {}),
                "page_structure_v3": dict(base_payload.get("page_structure_v3") or {}),
                "canonical_atoms": dict(base_payload.get("canonical_atoms") or {}),
                "atom_semantics": dict(base_payload.get("atom_semantics") or {}),
                "deterministic_page_skeleton": dict(base_payload.get("deterministic_page_skeleton") or {}),
                "stage2_style_plan": dict(base_payload.get("stage2_style_plan") or {}),
                "minimal_gate_report": dict(base_payload.get("minimal_gate_report") or {}),
                "candidate_ranking": dict(base_payload.get("candidate_ranking") or {}),
                "repair_report": dict(base_payload.get("repair_report") or {}),
                "segment_id_map": dict(base_payload.get("segment_id_map") or {}),
                "stage1_structural_annotations": dict(base_payload.get("stage1_structural_annotations") or {}),
                "stage2_design_layout": dict(base_payload.get("stage2_design_layout") or {}),
                "pipeline_contract_meta": dict(base_payload.get("pipeline_contract_meta") or {}),
                "qwen_layout_plan_v2": dict(base_payload.get("qwen_layout_plan_v2") or {}),
                "qwen_plan_meta": dict(base_payload.get("qwen_plan_meta") or {}),
                "layout_advice_v2": dict(base_payload.get("layout_advice_v2") or {}),
                "layout_advice_v3": dict(base_payload.get("layout_advice_v3") or {}),
                "layout_advice_meta": dict(base_payload.get("layout_advice_meta") or {}),
                "mm_parser_meta": dict(base_payload.get("mm_parser_meta") or {}),
                "assembly_meta": {
                    "used": bool(((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("assembly_used")),
                    "model": str((((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("assembly_model") or "")),
                    "fallback_reason": str((((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("assembly_fallback_reason") or "")),
                    "ui_ops_count": int((((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("assembly_ui_ops_count") or 0)),
                    "agent_tool_call_count": int((((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("assembly_agent_tool_call_count") or 0)),
                    "agent_trace_count": int((((loop_result.get("ui_plan") or {}).get("trace_meta") or {}).get("assembly_agent_trace_count") or 0)),
                },
                "component_registry_version": "reader_components_v2",
                "segment_map": dict(base_payload.get("segment_map") or {}),
                "segment_map_meta": dict(base_payload.get("segment_map_meta") or {}),
                "node_gate_report": dict(loop_result.get("node_gate_report") or {}),
                "toc_quality": float(base_payload.get("toc_quality") or 0.0),
                "phase1_compact_input": dict(base_payload.get("phase1_compact_input") or {}),
                "review_route_meta": dict(base_payload.get("review_route_meta") or {}),
                "style_cues": dict(base_payload.get("style_cues") or {}),
                "overlay_applied": False,
                "overlay_count": 0,
                "generated_at": datetime.utcnow().isoformat(),
            }

            payload = self._ensure_payload_contract(page=page_num, payload=payload)
            logger.info(
                "[ReaderComposeService] compose payload ready "
                f"paper={paper.id} page={page_num} status={str(payload.get('status') or '')} "
                f"degraded_reason={str(payload.get('degraded_reason') or '')}"
            )
            existing_same_signature = await self._read_payload_from_db(
                db=db,
                paper_id=int(paper.id),
                page=page_num,
                source_signature=source_signature,
            )
            existing_status = str((existing_same_signature or {}).get("status") or "").strip().lower()
            current_status = str(payload.get("status") or "").strip().lower()
            if existing_status == "done" and current_status != "done":
                logger.warning(
                    "[ReaderComposeService] keep previous done payload and skip degraded overwrite "
                    f"paper={paper.id} page={page_num} existing_status={existing_status} current_status={current_status}"
                )
                payload = self._ensure_payload_contract(page=page_num, payload=dict(existing_same_signature or {}))
            await self._upsert_payload_to_db(
                db=db,
                paper_id=int(paper.id),
                page=page_num,
                source_signature=source_signature,
                parser_version=COMPOSE_ENGINE_VERSION,
                build_mode=str(payload["build_mode"]),
                structure_confidence=max(
                    0.0, min(1.0, float(quality_report.get("overall") or 0.0))
                ),
                payload=payload,
            )
            await self._write_payload_to_redis(redis_key, payload)
            if compose_force_refresh and current_status == "done":
                cleanup_report = await self._cleanup_compose_sibling_caches(
                    db=db,
                    redis_key=redis_key,
                    paper_id=int(paper.id),
                    page=page_num,
                    source_signature=source_signature,
                    pipeline_mode=pipeline_mode,
                    pipeline_version=pipeline_version,
                )
                logger.info(
                    "[ReaderComposeService] compose sibling cache cleanup "
                    f"paper={paper.id} page={page_num} "
                    f"redis_deleted={int(cleanup_report.get('redis_deleted') or 0)} "
                    f"db_deleted={int(cleanup_report.get('db_deleted') or 0)}"
                )
            logger.info(
                "[ReaderComposeService] compose payload persisted "
                f"paper={paper.id} page={page_num}"
            )

            if publish_ready_event_enabled:
                await self._publish_reader_ready_event(
                    user_id=int(user_id),
                    paper_id=int(paper.id),
                    page=page_num,
                    source_signature=source_signature,
                )

            payload = self._with_cache_meta(payload, cache_hit=False, cache_layer="none")
            payload = await self._apply_overlay_for_user(
                db=db,
                user_id=int(user_id),
                paper_id=int(paper.id),
                page=page_num,
                source_signature=source_signature,
                payload=payload,
            )
            payload = self._ensure_payload_contract(page=page_num, payload=payload)
            return payload, ReaderComposeBuildMeta(
                cache_hit=False,
                cache_layer="none",
                build_mode=str(payload.get("build_mode") or "compose_agent"),
                source_signature=source_signature,
                source_sig_hash=sig_hash,
                iterations=int(quality_report.get("iterations") or 0),
                degraded=bool(quality_report.get("degraded")),
                stop_reason=str(quality_report.get("stop_reason") or "unknown"),
            )
        finally:
            if lock_keepalive_stop is not None:
                lock_keepalive_stop.set()
            if lock_keepalive_task is not None:
                try:
                    await lock_keepalive_task
                except Exception:
                    pass
            if lock_token is not None:
                await self._release_lock(lock_key, lock_token)

    async def _build_simplified_pipeline_result(
        self,
        *,
        db: AsyncSession,
        user_id: int,
        paper: Paper,
        page: int,
        base_payload: Dict[str, Any],
        style_intent: Optional[str],
        theme_mode: Optional[str],
        detail_level: str,
        compare_mode: bool,
        latency_budget_ms: int,
        selected_kb_id: Optional[int],
        pipeline_version: Optional[str] = None,
        progress_callback: Optional[ReaderComposeProgressCallback] = None,
    ) -> Dict[str, Any]:
        _ = pipeline_version
        return await self._build_simplified_pipeline_result_legacy(
            db=db,
            user_id=user_id,
            paper=paper,
            page=page,
            base_payload=base_payload,
            style_intent=style_intent,
            theme_mode=theme_mode,
            detail_level=detail_level,
            compare_mode=compare_mode,
            latency_budget_ms=latency_budget_ms,
            selected_kb_id=selected_kb_id,
            progress_callback=progress_callback,
        )

    @staticmethod
    def _layout_uid_group_kinds() -> set[str]:
        return {
            "title",
            "section_heading",
            "paragraph",
            "list",
            "figure",
            "table",
            "table_caption",
            "equation",
            "metadata",
            "doi",
            "header",
            "footer",
            "noise",
        }

    @staticmethod
    def _layout_uid_ai_reconstruction_component_kinds() -> set[str]:
        return {
            "heading",
            "paragraph",
            "list",
            "figure",
            "table",
            "equation",
        }

    def _build_layout_uid_prompt_payload(
        self,
        *,
        paper: Paper,
        page: int,
        grounding: Mapping[str, Any],
    ) -> Dict[str, Any]:
        layout_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
        ]
        compact_atoms: List[Dict[str, Any]] = []
        for atom in sorted(layout_atoms, key=lambda item: int(item.get("reading_order") or 0)):
            layout_id = str(atom.get("layout_id") or "").strip()
            if not layout_id:
                continue
            compact_atoms.append(
                {
                    "layout_id": layout_id,
                    "reading_order": int(atom.get("reading_order") or 0),
                    "layout_type": str(atom.get("layout_type") or "").strip().lower(),
                    "layout_sub_type": str(atom.get("layout_sub_type") or "").strip().lower(),
                    "node_kind": str(atom.get("node_kind") or "").strip().lower(),
                    "text": self._normalized_grounding_text(atom),
                    "include_in_main_flow": bool(atom.get("include_in_main_flow")),
                    "region_hint": str(atom.get("region_hint") or "").strip(),
                    "layout_pos": list(atom.get("layout_pos") or []),
                    "block_count": len(list(atom.get("blocks") or [])),
                }
            )
        return {
            "page_meta": {
                "paper_id": int(paper.id),
                "page": int(page),
                "paper_title": str(getattr(paper, "title", "") or "").strip(),
                "reader_mode": "read_layout_uid_v1",
            },
            "layout_atoms": compact_atoms,
            "rules": {
                "indivisible_unit": "layout_id",
                "exactly_once_assignment": True,
                "no_layout_split": True,
                "output_goal": "html_like_reading_flow",
                "allow_group_kinds": sorted(self._layout_uid_group_kinds()),
            },
        }

    @staticmethod
    def _layout_uid_combined_system_prompt() -> str:
        return (
            "You plan a single PDF page for the /read reader in one pass. "
            "The indivisible unit is layout_id (DocMind uniqueId). "
            "Never split a layout_id, never invent ids, and never modify ownership or geometry. "
            "Use the attached page image only as visual reference. "
            "You must output step_result.page_decision as "
            "{\"mode\":\"grounded\"|\"partial_reconstructed\"|\"fully_reconstructed\",\"reason\":\"...\",\"confidence\":0.0-1.0}. "
            "The allowed page_decision.mode values are grounded, partial_reconstructed, and fully_reconstructed only. "
            "Do two things in one JSON response: "
            "(1) return sparse text repairs only for layout_ids whose display text should change; "
            "(2) assign every layout_id exactly once, either in groups or omissions. "
            "Keep the source language; do not translate. "
            "Do not summarize or paraphrase. "
            "Prefer a clean HTML-like reading flow, not a complex generative UI page. "
            "Keep tables and equations as dedicated reading islands; do not flatten them into prose. "
            "For prose-like groups, preserve semantic paragraph boundaries. "
            "If a paragraph or table_caption group contains multiple semantic paragraphs, return them in group.paragraphs. "
            "Each paragraph item should look like {\"text\":\"...\",\"source_layout_ids\":[\"...\"]}. "
            "paragraphs are optional, but when provided they are the reader-facing paragraph structure and should be faithful. "
            "page_decision.mode grounded means return groups, omissions, and text_items. "
            "page_decision.mode partial_reconstructed means return groups, omissions, text_items, and reconstructed_components. "
            "page_decision.mode fully_reconstructed means return reconstructed_components, and groups may be omitted. "
            "Non-figure bbox values are reference only and not strict evidence. "
            "Figure bbox and visual_spec are for direct rough cropping, not later verification. "
            "For figure reconstruction, estimate one practical crop directly from the page image using the DocMind coarse visual boundary, "
            "the visible text positions, and approximate x/y relationships. "
            "Prefer the smallest bbox that still keeps the figure body readable, and exclude caption and page number as much as possible. "
            "Do not defer figure cropping to a later verifier; provide a usable rough crop immediately. "
            "For footer-like link items, preserve the URL exactly and recover obvious leading markers when visually clear. "
            "If a footer fragment is redundant, you may hide it by returning mode footer_hide_fragment. "
            "Classify DocMind as poor or unusable only when grounded reading would still require guesswork after OCR cleanup. "
            "Treat single-main-layout pages with collapsed block groups, garbled OCR, table-like noise, repeated placeholder tokens, "
            "or obvious semantic collapse as strong poor-grounding signals, but do not switch to reconstruction just because one of those signals appears in isolation. "
            "Do not stay grounded merely because layout_ids exist or because the page has nominal coverage. "
            "Use page_quality.grounding_warning as advisory evidence that deserves closer inspection, not as an automatic reconstruction trigger. "
            "If page_quality.coarse_visual_bbox_norm is present, treat it as the preferred coarse boundary for figure crops on collapsed pages, even when DocMind mislabeled the region as a table. "
            "For figure reconstruction, use the page image, the coarse DocMind boundary, and visible text positions to estimate one practical rough bbox. "
            "Keep the crop conservative enough to preserve the figure body, but trim caption and page-number noise as much as possible. "
            "If the warning suggests collapse or garble, classify DocMind as poor only when the page cannot still be read faithfully from the grounded layout. "
            "In that case set step_result.page_decision.mode = fully_reconstructed and provide step_result.reconstructed_components. "
            "If you also emit the legacy step_result.reconstruction field, keep it consistent with page_decision and reconstructed_components. "
            "Allowed reconstruction component kinds are heading, paragraph, list, figure, table, equation. "
            "Reconstruction components may optionally include bbox_norm in normalized page coordinates. "
            "Paragraph components may include bbox_norm on the component itself and on individual paragraph rows. "
            "Each paragraph row should look like {\"text\":\"...\",\"bbox_norm\":{\"x0\":0.1,\"y0\":0.2,\"x1\":0.9,\"y1\":0.3}}. "
            "paragraph components may include paragraphs:[{\"text\":\"...\",\"bbox_norm\":{\"x0\":0.1,\"y0\":0.2,\"x1\":0.9,\"y1\":0.3}}, ...] and bbox_norm. "
            "figure components may include caption, source_label, bbox_norm, and visual_spec. "
            "Use bbox_norm as the practical rough crop to use directly; mirror the same practical crop in visual_spec.seed_bbox_norm when possible. "
            "visual_spec should describe a practical rough figure-only crop that can be used directly without later verification. "
            "visual_spec may include seed_bbox_norm {x0,y0,x1,y1} in normalized page coordinates, "
            "must_include:[...], must_exclude:[...], region_description:\"...\", boundary_notes:\"...\", "
            "require_full_boundary:true/false, prefer_without_caption:true/false, allow_caption_if_needed:true/false, target_kind:\"figure\". "
            "Default to a practical rough figure crop with minimal whitespace and without the caption unless the caption is visually required to understand the figure. "
            "Use visible text positions and approximate x/y relationships to explain where the crop should start and stop. "
            "If the caption is needed, explain why and say exactly what part of the caption must remain inside the crop. "
            "Be explicit about the visible figure region, the main plot or diagram elements that must be inside it, and the boundaries that should be excluded. "
            "If the crop is only partially reconstructable, keep the figure body and add concise notes or partial_reconstruction guidance rather than pretending the crop is complete. "
            "Figure components may also include notes or reconstruction_notes for partial reconstruction intent, for example to keep the figure body while trimming noisy caption or prose. "
            "If the figure was misclassified as a table-like OCR artifact, do not flatten it into a table; keep a figure component with rough crop guidance and partial reconstruction notes. "
            "table components may include title, caption, headers:[...], rows:[[...],[...]] or row_objects:[{...}], raw_markdown. "
            "step_result.text_items should include ONLY changed layout_ids. "
            "Outside fully_reconstructed mode, step_result.groups and step_result.omissions together must cover every layout_id exactly once. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{\"page_decision\":{\"mode\":\"partial_reconstructed\",\"reason\":\"...\",\"confidence\":0.82},\"text_items\":["
            "{\"layout_id\":\"...\",\"normalized_text\":\"...\",\"reason\":\"...\",\"confidence\":0.94,\"mode\":\"ocr_cleanup\"}"
            "],\"groups\":[{\"group_id\":\"g1\",\"group_kind\":\"paragraph\",\"source_layout_ids\":[\"layout_id\"],"
            "\"paragraphs\":[{\"text\":\"...\",\"source_layout_ids\":[\"layout_id\"]}],\"rationale\":\"\"}],"
            "\"omissions\":[{\"layout_id\":\"...\",\"reason\":\"header\"}],"
            "\"reconstructed_components\":[{\"kind\":\"paragraph\",\"text\":\"...\",\"bbox_norm\":{\"x0\":0.1,\"y0\":0.2,\"x1\":0.9,\"y1\":0.3},"
            "\"paragraphs\":[{\"text\":\"...\",\"bbox_norm\":{\"x0\":0.1,\"y0\":0.2,\"x1\":0.9,\"y1\":0.3}}]},"
            "{\"kind\":\"figure\",\"caption\":\"...\",\"source_label\":\"Figure 4\",\"bbox_norm\":{\"x0\":0.08,\"y0\":0.16,\"x1\":0.92,\"y1\":0.74},"
            "\"visual_spec\":{\"seed_bbox_norm\":{\"x0\":0.08,\"y0\":0.16,\"x1\":0.92,\"y1\":0.74},"
            "\"must_include\":[\"all main plotted nodes\"],\"must_exclude\":[\"neighbor prose\"],"
            "\"region_description\":\"practical rough crop around the plotted figure only\",\"boundary_notes\":\"use visible text positions and x/y relationships; exclude caption if possible\","
            "\"require_full_boundary\":true,\"prefer_without_caption\":true,\"allow_caption_if_needed\":false,"
            "\"target_kind\":\"figure\"}}],"
            "\"notes\":[\"...\"]}}"
        )

    @staticmethod
    def _layout_uid_reconstruction_only_system_prompt() -> str:
        return (
            "You reconstruct a single PDF page for the /read reader because the provided DocMind grounding appears unusable. "
            "Use the attached page image as the primary evidence. "
            "Do not try to preserve layout_id ownership. "
            "Do not summarize the page; reconstruct a faithful reader-facing page. "
            "Treat a single collapsed block with garbled OCR, placeholder tokens, or broken semantic coverage as poor grounding and reconstruct directly. "
            "Keep the source language; do not translate. "
            "Return JSON with status and step_result.reconstruction only. "
            "Set step_result.reconstruction = "
            "{\"mode\":\"ai_reconstructed\",\"docmind_quality\":\"poor\",\"reason\":\"...\",\"confidence\":0.82,"
            "\"components\":[...],\"notes\":[...]}. "
            "Allowed reconstruction component kinds are heading, paragraph, list, figure, table, equation. "
            "Reconstruction components may optionally include bbox_norm in normalized page coordinates. "
            "Paragraph components may include paragraphs:[{\"text\":\"...\",\"bbox_norm\":{\"x0\":0.1,\"y0\":0.2,\"x1\":0.9,\"y1\":0.3}}, ...] "
            "and bbox_norm on the component itself. "
            "figure components may include caption, source_label, bbox_norm, and visual_spec. "
            "Use bbox_norm as the practical rough crop to use directly; mirror the same practical crop in visual_spec.seed_bbox_norm when possible. "
            "visual_spec may include seed_bbox_norm {x0,y0,x1,y1}, must_include:[...], must_exclude:[...], "
            "region_description:\"...\", boundary_notes:\"...\", require_full_boundary:true/false, "
            "prefer_without_caption:true/false, allow_caption_if_needed:true/false, target_kind:\"figure\". "
            "Default to a practical rough figure-only crop with tight but safe boundaries. Exclude the caption unless the caption is required to keep the figure intelligible. "
            "Use visible text positions and approximate x/y relationships to estimate the crop in the page image. "
            "If the caption is needed, say so explicitly in the visual_spec and keep only the caption fragment that is visually required. "
            "If the crop is only partially reconstructable, keep the figure body and add concise notes or partial_reconstruction guidance rather than treating the crop as complete. "
            "If the figure was misclassified as a table-like OCR artifact, keep the figure as a figure component and add rough crop guidance; do not collapse it into a table. "
            "If the page is mostly a figure or chart, prefer a FigurePanel plus concise supporting prose instead of dumping OCR garbage. "
            "If the page is mostly a table, reconstruct the table semantically with title/caption/headers/rows instead of preserving corrupted OCR. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{\"reconstruction\":{\"mode\":\"ai_reconstructed\",\"docmind_quality\":\"poor\","
            "\"reason\":\"...\",\"confidence\":0.82,\"components\":[{\"kind\":\"paragraph\",\"text\":\"...\"}],\"notes\":[\"...\"]}}}"
        )

    @staticmethod
    def _normalize_bbox_norm(raw_bbox: Any) -> Optional[Dict[str, float]]:
        if isinstance(raw_bbox, Mapping):
            source = raw_bbox
        elif isinstance(raw_bbox, (list, tuple)) and len(raw_bbox) >= 4:
            source = {
                "x0": raw_bbox[0],
                "y0": raw_bbox[1],
                "x1": raw_bbox[2],
                "y1": raw_bbox[3],
            }
        else:
            return None
        try:
            x0 = max(0.0, min(1.0, float(source.get("x0") or 0.0)))
            y0 = max(0.0, min(1.0, float(source.get("y0") or source.get("top") or 0.0)))
            x1 = max(0.0, min(1.0, float(source.get("x1") or 0.0)))
            y1 = max(0.0, min(1.0, float(source.get("y1") or source.get("bottom") or 0.0)))
        except Exception:
            return None
        if x1 - x0 < 0.02 or y1 - y0 < 0.02:
            return None
        return {
            "x0": round(x0, 4),
            "y0": round(y0, 4),
            "x1": round(x1, 4),
            "y1": round(y1, 4),
        }

    @staticmethod
    def _bbox_norm_union(bboxes: Sequence[Mapping[str, Any]]) -> Optional[Dict[str, float]]:
        normalized = [
            {
                "x0": float(bbox.get("x0") or 0.0),
                "y0": float(bbox.get("y0") or 0.0),
                "x1": float(bbox.get("x1") or 0.0),
                "y1": float(bbox.get("y1") or 0.0),
            }
            for bbox in list(bboxes or [])
            if isinstance(bbox, Mapping)
        ]
        if not normalized:
            return None
        try:
            x0 = min(item["x0"] for item in normalized)
            y0 = min(item["y0"] for item in normalized)
            x1 = max(item["x1"] for item in normalized)
            y1 = max(item["y1"] for item in normalized)
        except Exception:
            return None
        if x1 - x0 < 0.02 or y1 - y0 < 0.02:
            return None
        return {
            "x0": round(max(0.0, min(1.0, x0)), 4),
            "y0": round(max(0.0, min(1.0, y0)), 4),
            "x1": round(max(0.0, min(1.0, x1)), 4),
            "y1": round(max(0.0, min(1.0, y1)), 4),
        }

    @staticmethod
    def _bbox_norm_to_absolute_hint(
        *,
        bbox_norm: Mapping[str, Any],
        page_width: float,
        page_height: float,
    ) -> Optional[Dict[str, float]]:
        if not isinstance(bbox_norm, Mapping):
            return None
        try:
            x0 = float(bbox_norm.get("x0") or 0.0)
            y0 = float(bbox_norm.get("y0") or bbox_norm.get("top") or 0.0)
            x1 = float(bbox_norm.get("x1") or 0.0)
            y1 = float(bbox_norm.get("y1") or bbox_norm.get("bottom") or 0.0)
            if page_width > 0 and page_height > 0 and max(x0, y0, x1, y1) <= 1.5:
                x0 *= page_width
                x1 *= page_width
                y0 *= page_height
                y1 *= page_height
        except Exception:
            return None
        if x1 <= x0 or y1 <= y0:
            return None
        return {
            "x0": round(x0, 2),
            "x1": round(x1, 2),
            "top": round(y0, 2),
            "bottom": round(y1, 2),
            "page_width": page_width or None,
            "page_height": page_height or None,
        }

    @staticmethod
    def _bbox_hint_rect_polygon(bbox_hint: Mapping[str, Any]) -> List[Dict[str, float]]:
        try:
            x0 = float(bbox_hint.get("x0") or 0.0)
            x1 = float(bbox_hint.get("x1") or 0.0)
            top = float(bbox_hint.get("top") or 0.0)
            bottom = float(bbox_hint.get("bottom") or 0.0)
        except Exception:
            return []
        if x1 <= x0 or bottom <= top:
            return []
        return [
            {"x": x0, "y": top},
            {"x": x1, "y": top},
            {"x": x1, "y": bottom},
            {"x": x0, "y": bottom},
        ]

    def _build_ai_reconstructed_component_anchor_ref(
        self,
        *,
        page: int,
        component_id: str,
        component_kind: str,
        text_hint: str,
        bbox_norm: Optional[Mapping[str, Any]],
        page_width: float,
        page_height: float,
        anchor_index: int,
    ) -> Optional[Dict[str, Any]]:
        normalized_bbox_norm = self._normalize_bbox_norm(dict(bbox_norm or {})) if isinstance(bbox_norm, Mapping) else None
        bbox_hint = self._bbox_norm_to_absolute_hint(
            bbox_norm=normalized_bbox_norm or {},
            page_width=float(page_width or 0.0),
            page_height=float(page_height or 0.0),
        ) if normalized_bbox_norm else None
        if not bbox_hint:
            return None
        quote_text = self._normalize_spaces(str(text_hint or component_kind or ""))
        anchor_id = f"ai_bbox_v1:{int(page)}:{component_id or anchor_index}"
        canonical_block_id = f"ai_reconstructed_p{int(page)}_{component_id or anchor_index}"
        start_char = max(0, int(anchor_index) * 100)
        end_char = start_char + max(1, len(quote_text or component_kind or "anchor"))
        geometry = {
            "polygons": [
                {
                    "points": self._bbox_hint_rect_polygon(bbox_hint),
                    "source": "ai_reconstructed",
                    "component_id": str(component_id or f"comp_{anchor_index}"),
                }
            ],
            "page_width": float(page_width or 0.0) or None,
            "page_height": float(page_height or 0.0) or None,
        }
        return {
            "page": int(page),
            "start_char": start_char,
            "end_char": end_char,
            "quote": quote_text[:280] if quote_text else None,
            "quote_text": quote_text[:280] if quote_text else None,
            "anchor_id": anchor_id,
            "segment_index": 1,
            "segment_total": 1,
            "bbox_hint": bbox_hint,
            "canonical_block_id": canonical_block_id,
            "source_layout_id": str(component_id or canonical_block_id),
            "coord_version": "ai_bbox_v1",
            "anchor_confidence": 0.91,
            "anchor_v2": {
                "coord_version": "ai_bbox_v1",
                "canonical_block_id": canonical_block_id,
                "page": int(page),
                "start_char": start_char,
                "end_char": end_char,
            },
            "geometry_version": "poly_v1",
            "geometry": geometry,
            "source_word_ids": [],
            "source_char_ranges": [],
        }

    def _build_layout_uid_combined_prompt_payload(
        self,
        *,
        paper: Paper,
        page: int,
        grounding: Mapping[str, Any],
        payload: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        layout_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
        ]
        footer_bundles = self._build_layout_uid_footer_bundles(layout_atoms)
        footer_bundle_by_layout_id: Dict[str, Dict[str, Any]] = {}
        for bundle in footer_bundles:
            bundle_id = str(bundle.get("bundle_id") or "").strip()
            bundle_summary = {
                "bundle_id": bundle_id,
                "item_count": int(bundle.get("item_count") or 0),
                "reading_order_start": int(bundle.get("reading_order_start") or 0),
                "reading_order_end": int(bundle.get("reading_order_end") or 0),
            }
            for item in list(bundle.get("items") or []):
                if not isinstance(item, Mapping):
                    continue
                layout_id = str(item.get("layout_id") or "").strip()
                if layout_id:
                    footer_bundle_by_layout_id[layout_id] = bundle_summary

        compact_atoms: List[Dict[str, Any]] = []
        for atom in sorted(layout_atoms, key=lambda item: int(item.get("reading_order") or 0)):
            layout_id = str(atom.get("layout_id") or "").strip()
            if not layout_id:
                continue
            compact_atoms.append(
                {
                    "layout_id": layout_id,
                    "reading_order": int(atom.get("reading_order") or 0),
                    "layout_type": str(atom.get("layout_type") or "").strip().lower(),
                    "layout_sub_type": str(atom.get("layout_sub_type") or "").strip().lower(),
                    "node_kind": str(atom.get("node_kind") or "").strip().lower(),
                    "source_text": str(atom.get("clean_text") or atom.get("raw_text") or "").strip(),
                    "text": self._normalized_grounding_text(atom),
                    "include_in_main_flow": bool(atom.get("include_in_main_flow")),
                    "region_hint": str(atom.get("region_hint") or "").strip(),
                    "layout_pos": list(atom.get("layout_pos") or []),
                    "block_count": len(list(atom.get("blocks") or [])),
                    "alignment": str(atom.get("alignment") or "").strip().lower(),
                    "line_height": float(atom.get("line_height") or 0.0),
                    "footer_bundle": dict(footer_bundle_by_layout_id.get(layout_id) or {}),
                    "block_styles": [
                        {
                            "style_id": int(block.get("style_id") or 0),
                            "text": str(block.get("text") or "").strip(),
                        }
                        for block in list(atom.get("blocks") or [])
                        if isinstance(block, Mapping)
                    ],
                }
            )
        page_payload = dict(payload or {})
        page_structure_v3 = dict(page_payload.get("page_structure_v3") or {})
        grounding_warning = self._analyze_layout_uid_grounding_quality(
            grounding=grounding,
            payload=page_payload,
        )
        coarse_visual_bbox_norm = self._derive_layout_uid_coarse_visual_bbox_norm(
            grounding=grounding,
            payload=page_payload,
        )
        if coarse_visual_bbox_norm:
            grounding_warning["coarse_visual_bbox_norm"] = dict(coarse_visual_bbox_norm)
        return {
            "page_meta": {
                "paper_id": int(paper.id),
                "page": int(page),
                "paper_title": str(getattr(paper, "title", "") or "").strip(),
                "reader_mode": "read_layout_uid_v1_combined",
            },
            "page_quality": {
                "structure_confidence": round(float(page_payload.get("structure_confidence") or 0.0), 4),
                "page_payload_build_mode": str(page_payload.get("build_mode") or "").strip(),
                "repair_used": bool(page_payload.get("repair_used") or ((page_payload.get("repair_report") or {}).get("used"))),
                "layout_count": len(compact_atoms),
                "block_group_count": len(list(page_structure_v3.get("block_groups") or [])),
                "grounding_warning": grounding_warning,
                "coarse_visual_bbox_norm": dict(coarse_visual_bbox_norm) if coarse_visual_bbox_norm else None,
            },
            "layout_atoms": compact_atoms,
            "footer_bundles": footer_bundles,
            "rules": {
                "indivisible_unit": "layout_id",
                "exact_group_assignment": True,
                "text_item_mode": "sparse_diff_only",
                "no_layout_split": True,
                "forbid_translation": True,
                "forbid_geometry_mutation": True,
                "forbid_ownership_mutation": True,
                "output_goal": "html_like_reading_flow",
                "allow_group_kinds": sorted(self._layout_uid_group_kinds()),
                "allow_reconstruction_component_kinds": sorted(self._layout_uid_ai_reconstruction_component_kinds()),
                "allowed_repairs": [
                    "ocr_cleanup",
                    "superscript_or_subscript_recovery",
                    "spacing_repair",
                    "hyphenation_repair",
                    "heading_or_list_stitching",
                    "citation_marker_cleanup",
                    "footer_bundle_rewrite",
                    "footer_bundle_hide_fragment",
                ],
            },
        }

    def _collect_layout_uid_grounding_text_samples(
        self,
        *,
        grounding: Mapping[str, Any],
        payload: Optional[Mapping[str, Any]] = None,
    ) -> List[str]:
        samples: List[str] = []
        seen: Set[str] = set()

        def _push(value: Any) -> None:
            text = self._normalize_spaces(str(value or ""))
            if not text:
                return
            key = text.lower()
            if key in seen:
                return
            seen.add(key)
            samples.append(text)

        for atom in list((grounding or {}).get("layout_atoms") or []):
            if not isinstance(atom, Mapping):
                continue
            _push(atom.get("normalized_text"))
            _push(atom.get("clean_text"))
            _push(atom.get("raw_text"))
            for block in list(atom.get("blocks") or []):
                if isinstance(block, Mapping):
                    _push(block.get("text"))

        page_structure_v3 = dict((payload or {}).get("page_structure_v3") or {})
        for row in list(page_structure_v3.get("block_groups") or []):
            if isinstance(row, Mapping):
                _push(row.get("text"))

        return samples[:24]

    def _looks_like_layout_uid_ocr_garbage(self, text: Any) -> bool:
        value = self._normalize_spaces(str(text or ""))
        if len(value) < 24:
            return False
        lower = value.lower()
        if any(token in lower for token in ("<ped>", "<pad>", "<eos>", "<sos>", "<so3>", "<s0")):
            return True
        compact = re.sub(r"\s+", "", value)
        if not compact:
            return False
        weird_ratio = (
            sum(1 for ch in compact if not (ch.isalnum() or ch in ".,;:!?()[]{}%+-=/&_#*'\"|:<>"))
            / max(1, len(compact))
        )
        if weird_ratio >= 0.18:
            return True
        glitch_markers = len(re.findall(r"(?:<[^>]{2,8}>|[A-Za-z]{1,}![A-Za-z]{1,}|[A-Za-z]{1,}\^[A-Za-z]{1,})", value))
        if glitch_markers >= 2:
            return True
        words = re.findall(r"[A-Za-z]{3,}", value)
        if len(words) >= 6:
            vowelish = [word for word in words if re.search(r"[aeiouAEIOU]", word)]
            if (len(vowelish) / max(1, len(words))) < 0.45:
                return True
        return False

    def _analyze_layout_uid_grounding_quality(
        self,
        *,
        grounding: Mapping[str, Any],
        payload: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        layout_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
        ]
        main_atoms = [
            row
            for row in layout_atoms
            if bool(row.get("include_in_main_flow"))
        ] or list(layout_atoms)
        page_payload = dict(payload or {})
        page_structure_v3 = dict(page_payload.get("page_structure_v3") or {})
        block_groups = [
            dict(row)
            for row in list(page_structure_v3.get("block_groups") or [])
            if isinstance(row, Mapping)
        ]
        text_samples = self._collect_layout_uid_grounding_text_samples(
            grounding=grounding,
            payload=page_payload,
        )
        suspicious_text_samples = [
            text[:220]
            for text in text_samples
            if self._looks_like_layout_uid_ocr_garbage(text)
        ]
        main_layout_types = {
            str(row.get("layout_type") or "").strip().lower()
            for row in main_atoms
            if str(row.get("layout_type") or "").strip()
        }
        single_main_layout = len(main_atoms) <= 1
        collapsed_block_groups = len(block_groups) <= 1
        only_table_like_main = bool(single_main_layout and main_layout_types and main_layout_types.issubset({"table", "figure", "text"}))
        should_force_reconstruction = bool(
            suspicious_text_samples
            and single_main_layout
            and collapsed_block_groups
            and only_table_like_main
        )
        return {
            "single_main_layout": bool(single_main_layout),
            "collapsed_block_groups": bool(collapsed_block_groups),
            "main_layout_types": sorted(main_layout_types),
            "suspicious_ocr": bool(suspicious_text_samples),
            "suspicious_text_examples": suspicious_text_samples[:3],
            "reconstruction_hint": {
                "recommended": bool(should_force_reconstruction),
                "advisory_only": True,
                "reason": (
                    "single_main_layout_plus_collapsed_block_groups_plus_garbled_ocr"
                    if should_force_reconstruction else
                    "no_strong_reconstruction_hint"
                ),
            },
            "should_force_reconstruction": False,
        }

    def _build_layout_uid_reconstruction_only_prompt_payload(
        self,
        *,
        paper: Paper,
        page: int,
        grounding: Mapping[str, Any],
        payload: Optional[Mapping[str, Any]],
        grouping_plan: Mapping[str, Any],
        text_validation: Mapping[str, Any],
        retry_reason: str,
    ) -> Dict[str, Any]:
        combined_payload = self._build_layout_uid_combined_prompt_payload(
            paper=paper,
            page=page,
            grounding=grounding,
            payload=payload,
        )
        page_quality = dict(combined_payload.get("page_quality") or {})
        grounding_warning = dict(page_quality.get("grounding_warning") or {})
        return {
            "page_meta": dict(combined_payload.get("page_meta") or {}),
            "page_quality": page_quality,
            "layout_atoms": list(combined_payload.get("layout_atoms") or []),
            "retry_reason": retry_reason,
            "grounding_warning": grounding_warning,
            "previous_grounded_attempt": {
                "group_count": len(list((grouping_plan or {}).get("groups") or [])),
                "group_kinds": [
                    str(row.get("group_kind") or "").strip().lower()
                    for row in list((grouping_plan or {}).get("groups") or [])
                    if isinstance(row, Mapping) and str(row.get("group_kind") or "").strip()
                ][:8],
                "text_validation_errors": [
                    str(item).strip()
                    for item in list((text_validation or {}).get("errors") or [])
                    if str(item).strip()
                ][:8],
                "suspicious_text_examples": list(grounding_warning.get("suspicious_text_examples") or [])[:3],
            },
            "rules": {
                "mode": "reconstruction_only",
                "allowed_component_kinds": sorted(self._layout_uid_ai_reconstruction_component_kinds()),
                "prefer_faithful_reader_page": True,
                "preserve_source_language": True,
            },
        }

    def _select_ai_reconstructed_figure_crop_source_asset(
        self,
        *,
        rendered_page_image_url: str,
        rendered_page_image_path: str,
        grounding: Mapping[str, Any],
    ) -> Dict[str, Any]:
        def _build_candidate(*, source: str, image_url: str, image_path: str) -> Optional[Dict[str, Any]]:
            local_path = str(image_path or "").strip()
            if not local_path or not os.path.exists(local_path):
                return None
            width, height = self._resolve_grounding_page_image_size(
                page_image_url=str(image_url or "").strip(),
                page_image_path=local_path,
            )
            if not width or not height:
                return None
            return {
                "source": source,
                "url": str(image_url or "").strip(),
                "path": local_path,
                "width": float(width),
                "height": float(height),
                "area": float(width) * float(height),
                "local_cached": True,
            }

        page_render_candidate = _build_candidate(
            source="page_render_asset",
            image_url=rendered_page_image_url,
            image_path=rendered_page_image_path,
        )
        if page_render_candidate:
            return page_render_candidate
        grounding_page_image = dict((grounding or {}).get("page_image") or {})
        grounding_candidate = _build_candidate(
            source=str(grounding_page_image.get("source") or "grounding_page_image").strip() or "grounding_page_image",
            image_url=str(grounding_page_image.get("url") or "").strip(),
            image_path=str(grounding_page_image.get("path") or "").strip(),
        )
        if grounding_candidate:
            return grounding_candidate
        return {
            "source": "",
            "url": "",
            "path": "",
            "width": 0.0,
            "height": 0.0,
            "local_cached": False,
        }

    @staticmethod
    def _merge_usage_metrics(*usage_items: Mapping[str, Any]) -> Dict[str, int]:
        prompt_tokens = 0
        completion_tokens = 0
        total_tokens = 0
        for item in list(usage_items or []):
            if not isinstance(item, Mapping):
                continue
            prompt_tokens += int(item.get("prompt_tokens") or 0)
            completion_tokens += int(item.get("completion_tokens") or 0)
            total_tokens += int(item.get("total_tokens") or 0)
        return {
            "prompt_tokens": prompt_tokens,
            "completion_tokens": completion_tokens,
            "total_tokens": total_tokens,
        }

    @staticmethod
    def _layout_uid_grouping_system_prompt() -> str:
        return (
            "You organize a single PDF page for the /read reader. "
            "The indivisible unit is layout_id (DocMind uniqueId). "
            "Never split a layout_id, never invent ids, and never modify ownership. "
            "Use the attached page image only as visual reference. "
            "Return JSON with status and step_result. "
            "Each layout_id must be assigned exactly once, either in groups or omissions. "
            "Prefer a clean HTML-like reading flow, not a complex generative UI page. "
            "Keep tables and equations as dedicated reading islands; do not flatten them into prose. "
            "Keep the source language; do not translate. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{\"groups\":[{\"group_id\":\"g1\",\"group_kind\":\"paragraph\","
            "\"source_layout_ids\":[\"layout_id\"],\"rationale\":\"\"}],"
            "\"omissions\":[{\"layout_id\":\"...\",\"reason\":\"header\"}],\"notes\":[\"...\"]}}"
        )

    @staticmethod
    def _layout_uid_text_normalization_system_prompt() -> str:
        return (
            "You normalize display text for the /read reader. "
            "The indivisible unit is layout_id (DocMind uniqueId). "
            "Use the attached page image only as visual reference. "
            "You may repair OCR and style artifacts such as superscripts, subscripts, broken spacing, broken list markers, "
            "title stitching, citation-marker bleed, hyphenation leftovers, and footer/header link footnotes. "
            "For footer-like link items, preserve the URL exactly and recover leading footnote/reference markers such as ^6, ^7, ^8, ^9 when visually obvious. "
            "You may use footer_bundles context to normalize sequential footer items together, especially when marker-only layouts, noisy URLs, page numbers, and sibling footnotes appear in the same local group. "
            "For footer bundles, you may keep one sibling as the readable final footnote/link and hide redundant fragments by returning an empty normalized_text with mode footer_hide_fragment. "
            "Do not invent new URLs, but you may repair obvious OCR pollution around an existing URL or footnote marker by looking at the page image and nearby footer siblings. "
            "Do not translate, do not summarize, do not paraphrase, do not change meaning, and do not change ownership or geometry. "
            "Return JSON with status and step_result. "
            "Each candidate layout_id must appear exactly once in items. "
            "If no change is needed, return the source text unchanged and explain briefly. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{\"items\":["
            "{\"layout_id\":\"...\",\"normalized_text\":\"...\",\"reason\":\"...\",\"confidence\":0.94,\"mode\":\"ocr_cleanup\"}"
            "],\"notes\":[\"...\"]}}"
        )

    @staticmethod
    def _layout_uid_text_normalization_allowed_node_kinds() -> Set[str]:
        return {
            "title",
            "section_heading",
            "paragraph",
            "list",
            "figure_caption",
            "table_caption",
            "metadata",
            "doi",
            "header",
            "footer",
        }

    @staticmethod
    def _normalized_grounding_text(atom: Mapping[str, Any]) -> str:
        return str(
            atom.get("normalized_text")
            or atom.get("clean_text")
            or atom.get("raw_text")
            or ""
        ).strip()

    def _build_layout_uid_text_normalization_prompt_payload(
        self,
        *,
        page: int,
        grounding: Mapping[str, Any],
    ) -> Dict[str, Any]:
        layout_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
        ]
        footer_bundles = self._build_layout_uid_footer_bundles(layout_atoms)
        footer_bundle_by_layout_id: Dict[str, Dict[str, Any]] = {}
        for bundle in footer_bundles:
            bundle_id = str(bundle.get("bundle_id") or "").strip()
            bundle_summary = {
                "bundle_id": bundle_id,
                "item_count": int(bundle.get("item_count") or 0),
                "reading_order_start": int(bundle.get("reading_order_start") or 0),
                "reading_order_end": int(bundle.get("reading_order_end") or 0),
            }
            for item in list(bundle.get("items") or []):
                if not isinstance(item, Mapping):
                    continue
                layout_id = str(item.get("layout_id") or "").strip()
                if layout_id:
                    footer_bundle_by_layout_id[layout_id] = bundle_summary
        allowed_kinds = self._layout_uid_text_normalization_allowed_node_kinds()
        candidates: List[Dict[str, Any]] = []
        for atom in sorted(layout_atoms, key=lambda item: int(item.get("reading_order") or 0)):
            layout_id = str(atom.get("layout_id") or "").strip()
            node_kind = str(atom.get("node_kind") or "").strip().lower()
            source_text = str(atom.get("clean_text") or atom.get("raw_text") or "").strip()
            if not layout_id or not source_text or node_kind not in allowed_kinds:
                continue
            if not bool(atom.get("include_in_main_flow")) and node_kind not in {"metadata", "doi", "header", "footer"}:
                continue
            candidates.append(
                {
                    "layout_id": layout_id,
                    "reading_order": int(atom.get("reading_order") or 0),
                    "node_kind": node_kind,
                    "layout_type": str(atom.get("layout_type") or "").strip().lower(),
                    "layout_sub_type": str(atom.get("layout_sub_type") or "").strip().lower(),
                    "source_text": source_text,
                    "alignment": str(atom.get("alignment") or "").strip().lower(),
                    "line_height": float(atom.get("line_height") or 0.0),
                    "footer_bundle": dict(footer_bundle_by_layout_id.get(layout_id) or {}),
                    "block_styles": [
                        {
                            "style_id": int(block.get("style_id") or 0),
                            "text": str(block.get("text") or "").strip(),
                        }
                        for block in list(atom.get("blocks") or [])
                        if isinstance(block, Mapping)
                    ],
                }
            )
        return {
            "page_meta": {
                "page": int(page),
                "reader_mode": "read_layout_uid_v1_text_normalization",
            },
            "layout_atoms": candidates,
            "footer_bundles": footer_bundles,
            "rules": {
                "task": "normalize_display_text_only",
                "exactly_once_assignment": True,
                "forbid_translation": True,
                "forbid_geometry_mutation": True,
                "forbid_ownership_mutation": True,
                "allowed_repairs": [
                    "ocr_cleanup",
                    "superscript_or_subscript_recovery",
                    "spacing_repair",
                    "hyphenation_repair",
                    "heading_or_list_stitching",
                    "citation_marker_cleanup",
                    "footer_bundle_rewrite",
                    "footer_bundle_hide_fragment",
                ],
            },
        }

    def _build_layout_uid_footer_bundles(
        self,
        layout_atoms: Sequence[Mapping[str, Any]],
    ) -> List[Dict[str, Any]]:
        footer_atoms = [
            dict(atom)
            for atom in list(layout_atoms or [])
            if isinstance(atom, Mapping)
            and str(atom.get("node_kind") or "").strip().lower() == "footer"
            and str(atom.get("layout_id") or "").strip()
        ]
        if not footer_atoms:
            return []
        footer_atoms.sort(key=lambda item: int(item.get("reading_order") or 0))

        bundles: List[List[Dict[str, Any]]] = []
        current_bundle: List[Dict[str, Any]] = []
        previous_order: Optional[int] = None
        for atom in footer_atoms:
            reading_order = int(atom.get("reading_order") or 0)
            if current_bundle and previous_order is not None and reading_order - previous_order > 2:
                bundles.append(current_bundle)
                current_bundle = []
            current_bundle.append(atom)
            previous_order = reading_order
        if current_bundle:
            bundles.append(current_bundle)

        result: List[Dict[str, Any]] = []
        for idx, bundle in enumerate(bundles, start=1):
            items: List[Dict[str, Any]] = []
            for atom in bundle:
                source_text = str(atom.get("clean_text") or atom.get("raw_text") or "").strip()
                text_for_url = source_text or str(atom.get("normalized_text") or "").strip()
                primary_style_id = 0
                block_styles = [
                    dict(block)
                    for block in list(atom.get("blocks") or [])
                    if isinstance(block, Mapping)
                ]
                if block_styles:
                    primary_style_id = int((block_styles[0] or {}).get("style_id") or 0)
                items.append(
                    {
                        "layout_id": str(atom.get("layout_id") or "").strip(),
                        "reading_order": int(atom.get("reading_order") or 0),
                        "source_text": source_text,
                        "layout_type": str(atom.get("layout_type") or "").strip().lower(),
                        "layout_sub_type": str(atom.get("layout_sub_type") or "").strip().lower(),
                        "primary_style_id": primary_style_id,
                        "contains_url": bool(self._extract_url_from_footer_text(text_for_url)),
                        "is_marker_only": bool(re.fullmatch(r"[\^\[\(]?[0-9]{1,3}[\]\)]?", source_text)),
                    }
                )
            result.append(
                {
                    "bundle_id": f"footer_bundle_{idx}",
                    "item_count": len(items),
                    "reading_order_start": int((items[0] or {}).get("reading_order") or 0),
                    "reading_order_end": int((items[-1] or {}).get("reading_order") or 0),
                    "items": items,
                }
            )
        return result

    def _normalize_layout_uid_text_normalization_plan(
        self,
        *,
        grounding: Mapping[str, Any],
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        candidate_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
            and str(row.get("node_kind") or "").strip().lower() in self._layout_uid_text_normalization_allowed_node_kinds()
            and str(row.get("layout_id") or "").strip()
            and str(row.get("clean_text") or row.get("raw_text") or "").strip()
            and (
                bool(row.get("include_in_main_flow"))
                or str(row.get("node_kind") or "").strip().lower() in {"metadata", "doi", "header", "footer"}
            )
        ]
        source_text_by_id = {
            str(row.get("layout_id") or "").strip(): str(row.get("clean_text") or row.get("raw_text") or "").strip()
            for row in candidate_atoms
        }
        known_ids = set(source_text_by_id.keys())
        used_ids: List[str] = []
        normalized_items: List[Dict[str, Any]] = []
        errors: List[str] = []

        for raw_item in list((step_result or {}).get("items") or []):
            if not isinstance(raw_item, Mapping):
                continue
            layout_id = str(raw_item.get("layout_id") or "").strip()
            if not layout_id:
                continue
            if layout_id not in known_ids:
                errors.append(f"unknown_layout_id:{layout_id}")
                continue
            used_ids.append(layout_id)
            source_text = source_text_by_id.get(layout_id, "")
            normalized_text = self._normalize_spaces(str(raw_item.get("normalized_text") or source_text))
            reason = self._normalize_spaces(str(raw_item.get("reason") or ""))
            mode = self._normalize_spaces(str(raw_item.get("mode") or "")) or "no_change"
            allow_hidden_fragment = mode in {"footer_hide_fragment", "hide_fragment", "footer_fragment_hidden"}
            if allow_hidden_fragment:
                normalized_text = ""
            confidence = 0.0
            try:
                confidence = max(0.0, min(1.0, float(raw_item.get("confidence") or 0.0)))
            except Exception:
                confidence = 0.0
                errors.append(f"invalid_confidence:{layout_id}")
            if len(normalized_text) > 1200:
                errors.append(f"normalized_text_too_long:{layout_id}")
                normalized_text = source_text
            changed = allow_hidden_fragment or bool(normalized_text and normalized_text != source_text)
            normalized_items.append(
                {
                    "layout_id": layout_id,
                    "source_text": source_text,
                    "normalized_text": normalized_text if changed else source_text,
                    "reason": reason if changed else "",
                    "mode": mode if changed else "no_change",
                    "confidence": confidence if changed else 0.0,
                    "changed": changed,
                }
            )

        duplicates = sorted({layout_id for layout_id in used_ids if used_ids.count(layout_id) > 1})
        if duplicates:
            errors.extend([f"duplicate_layout_id:{layout_id}" for layout_id in duplicates])
        missing = [layout_id for layout_id in source_text_by_id if layout_id not in set(used_ids)]
        if missing:
            errors.extend([f"missing_layout_id:{layout_id}" for layout_id in missing])

        if errors:
            return {
                "items": [],
                "notes": ["deterministic_text_normalization_fallback"],
            }, {
                "passed": False,
                "errors": errors,
                "fallback_used": True,
            }

        changed_items = [dict(item) for item in normalized_items if bool(item.get("changed"))]
        return {
            "items": changed_items,
            "notes": [
                str(item).strip()
                for item in list((step_result or {}).get("notes") or [])
                if str(item).strip()
            ],
        }, {
            "passed": True,
            "errors": [],
            "fallback_used": False,
        }

    def _normalize_layout_uid_sparse_text_normalization_plan(
        self,
        *,
        grounding: Mapping[str, Any],
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        candidate_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
            and str(row.get("node_kind") or "").strip().lower() in self._layout_uid_text_normalization_allowed_node_kinds()
            and str(row.get("layout_id") or "").strip()
            and str(row.get("clean_text") or row.get("raw_text") or "").strip()
            and (
                bool(row.get("include_in_main_flow"))
                or str(row.get("node_kind") or "").strip().lower() in {"metadata", "doi", "header", "footer"}
            )
        ]
        source_text_by_id = {
            str(row.get("layout_id") or "").strip(): str(row.get("clean_text") or row.get("raw_text") or "").strip()
            for row in candidate_atoms
        }
        known_ids = set(source_text_by_id.keys())
        used_ids: List[str] = []
        normalized_items: List[Dict[str, Any]] = []
        errors: List[str] = []

        raw_items = (
            list((step_result or {}).get("text_items") or [])
            or list((step_result or {}).get("normalizations") or [])
            or list((step_result or {}).get("items") or [])
        )
        for raw_item in raw_items:
            if not isinstance(raw_item, Mapping):
                continue
            layout_id = str(raw_item.get("layout_id") or "").strip()
            if not layout_id:
                continue
            if layout_id not in known_ids:
                errors.append(f"unknown_layout_id:{layout_id}")
                continue
            used_ids.append(layout_id)
            source_text = source_text_by_id.get(layout_id, "")
            normalized_text = self._normalize_spaces(str(raw_item.get("normalized_text") or source_text))
            reason = self._normalize_spaces(str(raw_item.get("reason") or ""))
            mode = self._normalize_spaces(str(raw_item.get("mode") or "")) or "no_change"
            allow_hidden_fragment = mode in {"footer_hide_fragment", "hide_fragment", "footer_fragment_hidden"}
            if allow_hidden_fragment:
                normalized_text = ""
            confidence = 0.0
            try:
                confidence = max(0.0, min(1.0, float(raw_item.get("confidence") or 0.0)))
            except Exception:
                confidence = 0.0
                errors.append(f"invalid_confidence:{layout_id}")
            if len(normalized_text) > 1200:
                errors.append(f"normalized_text_too_long:{layout_id}")
                normalized_text = source_text
            changed = allow_hidden_fragment or bool(normalized_text and normalized_text != source_text)
            if not changed:
                continue
            normalized_items.append(
                {
                    "layout_id": layout_id,
                    "source_text": source_text,
                    "normalized_text": normalized_text if allow_hidden_fragment else normalized_text,
                    "reason": reason,
                    "mode": mode,
                    "confidence": confidence,
                    "changed": True,
                }
            )

        duplicates = sorted({layout_id for layout_id in used_ids if used_ids.count(layout_id) > 1})
        if duplicates:
            errors.extend([f"duplicate_layout_id:{layout_id}" for layout_id in duplicates])

        if errors:
            return {
                "items": [],
                "notes": ["deterministic_text_normalization_fallback"],
            }, {
                "passed": False,
                "errors": errors,
                "fallback_used": True,
            }

        return {
            "items": normalized_items,
            "notes": [
                str(item).strip()
                for item in list((step_result or {}).get("notes") or [])
                if str(item).strip()
            ],
        }, {
            "passed": True,
            "errors": [],
            "fallback_used": False,
        }

    def _apply_layout_uid_text_normalization_to_grounding(
        self,
        *,
        grounding: Mapping[str, Any],
        normalization_plan: Mapping[str, Any],
    ) -> Dict[str, Any]:
        next_grounding = dict(grounding or {})
        items = [
            dict(row)
            for row in list((normalization_plan or {}).get("items") or [])
            if isinstance(row, Mapping) and str(row.get("layout_id") or "").strip()
        ]
        if not items:
            return next_grounding
        item_by_id = {
            str(row.get("layout_id") or "").strip(): dict(row)
            for row in items
        }
        updated_atoms: List[Dict[str, Any]] = []
        for raw_atom in list((grounding or {}).get("layout_atoms") or []):
            if not isinstance(raw_atom, Mapping):
                continue
            atom = dict(raw_atom)
            layout_id = str(atom.get("layout_id") or "").strip()
            normalized = dict(item_by_id.get(layout_id) or {})
            if normalized:
                atom["normalized_text"] = str(normalized.get("normalized_text") or "").strip()
                atom["normalization_reason"] = str(normalized.get("reason") or "").strip()
                atom["normalization_mode"] = str(normalized.get("mode") or "").strip()
                atom["normalization_confidence"] = float(normalized.get("confidence") or 0.0)
            updated_atoms.append(atom)
        updated_atoms = self._backfill_footer_link_normalizations(updated_atoms)
        atom_text_by_id = {
            str(atom.get("layout_id") or "").strip(): str(atom.get("normalized_text") or "").strip()
            for atom in updated_atoms
            if str(atom.get("layout_id") or "").strip()
        }
        atom_reason_by_id = {
            str(atom.get("layout_id") or "").strip(): {
                "reason": str(atom.get("normalization_reason") or "").strip(),
                "mode": str(atom.get("normalization_mode") or "").strip(),
                "confidence": atom.get("normalization_confidence"),
            }
            for atom in updated_atoms
            if str(atom.get("layout_id") or "").strip()
        }
        updated_nodes: List[Dict[str, Any]] = []
        for raw_node in list((grounding or {}).get("reading_nodes") or []):
            if not isinstance(raw_node, Mapping):
                continue
            node = dict(raw_node)
            source_layout_ids = [
                str(item).strip()
                for item in list(node.get("source_layout_ids") or [])
                if str(item).strip()
            ]
            normalized_parts = [atom_text_by_id.get(layout_id, "").strip() for layout_id in source_layout_ids if atom_text_by_id.get(layout_id, "").strip()]
            if normalized_parts:
                node["normalized_text"] = "\n\n".join(normalized_parts).strip()
                primary_layout_id = source_layout_ids[0]
                node_meta = atom_reason_by_id.get(primary_layout_id) or {}
                node["normalization_reason"] = str(node_meta.get("reason") or "").strip()
                node["normalization_mode"] = str(node_meta.get("mode") or "").strip()
                node["normalization_confidence"] = node_meta.get("confidence")
            updated_nodes.append(node)
        next_meta = dict(next_grounding.get("meta") or {})
        next_grounding["layout_atoms"] = updated_atoms
        next_grounding["reading_nodes"] = updated_nodes
        normalization_summary = self._build_grounding_normalization_summary(updated_atoms)
        if normalization_summary:
            next_meta["normalization_summary"] = normalization_summary
        next_grounding["meta"] = next_meta
        return next_grounding

    @staticmethod
    def _extract_url_from_footer_text(text: str) -> str:
        match = re.search(r"https?://\S+", str(text or "").strip(), flags=re.IGNORECASE)
        if not match:
            return ""
        return str(match.group(0) or "").strip().rstrip(".,;:)]}>")

    @staticmethod
    def _extract_superscript_marker(text: str) -> Optional[int]:
        match = re.match(r"^\^(\d{1,3})\b", str(text or "").strip())
        if not match:
            return None
        try:
            return int(match.group(1))
        except Exception:
            return None

    def _backfill_footer_link_normalizations(
        self,
        layout_atoms: Sequence[Mapping[str, Any]],
    ) -> List[Dict[str, Any]]:
        updated_atoms = [dict(atom) for atom in list(layout_atoms or []) if isinstance(atom, Mapping)]
        footer_atoms = sorted(
            [
                atom
                for atom in updated_atoms
                if str(atom.get("node_kind") or "").strip().lower() == "footer"
            ],
            key=lambda atom: int(atom.get("reading_order") or 0),
        )
        next_marker: Optional[int] = None
        for atom in footer_atoms:
            source_text = str(atom.get("clean_text") or atom.get("raw_text") or "").strip()
            normalized_text = str(atom.get("normalized_text") or "").strip()
            normalization_mode = str(atom.get("normalization_mode") or "").strip().lower()
            if normalization_mode in {"footer_hide_fragment", "hide_fragment", "footer_fragment_hidden"}:
                continue
            known_marker = self._extract_superscript_marker(normalized_text)
            if known_marker is not None:
                next_marker = known_marker + 1
                continue
            canonical_url = self._extract_url_from_footer_text(source_text)
            if not canonical_url:
                continue
            if normalized_text and normalized_text != source_text:
                continue
            fallback_text = canonical_url
            if next_marker is not None:
                fallback_text = f"^{next_marker} {canonical_url}"
                next_marker += 1
            atom["normalized_text"] = fallback_text
            current_reason = str(atom.get("normalization_reason") or "").strip()
            current_mode = str(atom.get("normalization_mode") or "").strip()
            atom["normalization_reason"] = current_reason if current_reason and current_reason != "no_change" else "footer_link_cleanup"
            atom["normalization_mode"] = current_mode if current_mode and current_mode != "no_change" else "footer_link_fallback"
            atom["normalization_confidence"] = atom.get("normalization_confidence") if atom.get("normalization_confidence") not in (None, "", 0, 0.0) else 0.62
        return updated_atoms

    def _build_grounding_normalization_summary(
        self,
        layout_atoms: Sequence[Mapping[str, Any]],
    ) -> Optional[Dict[str, Any]]:
        changed_items: List[Dict[str, Any]] = []
        for atom in list(layout_atoms or []):
            if not isinstance(atom, Mapping):
                continue
            layout_id = str(atom.get("layout_id") or "").strip()
            source_text = str(atom.get("clean_text") or atom.get("raw_text") or "").strip()
            normalized_text = str(atom.get("normalized_text") or "").strip()
            if not layout_id or not source_text or not normalized_text or normalized_text == source_text:
                continue
            changed_items.append(
                {
                    "layout_id": layout_id,
                    "source_text": source_text,
                    "normalized_text": normalized_text,
                    "reason": str(atom.get("normalization_reason") or "").strip(),
                    "mode": str(atom.get("normalization_mode") or "").strip(),
                    "confidence": float(atom.get("normalization_confidence") or 0.0),
                }
            )
        if not changed_items:
            return None
        return {
            "item_count": len(changed_items),
            "items": changed_items[:24],
        }

    def _merge_existing_grounding_enrichments(
        self,
        *,
        existing_grounding: Mapping[str, Any],
        rebuilt_grounding: Mapping[str, Any],
    ) -> Dict[str, Any]:
        merged = dict(rebuilt_grounding or {})
        if not isinstance(existing_grounding, Mapping):
            return merged

        existing_page_image = dict((existing_grounding or {}).get("page_image") or {})
        rebuilt_page_image = dict((rebuilt_grounding or {}).get("page_image") or {})
        if rebuilt_page_image:
            merged_page_image = dict(rebuilt_page_image)
            for key in ("width", "height"):
                if merged_page_image.get(key) in (None, "", 0, 0.0, False) and existing_page_image.get(key) not in (
                    None,
                    "",
                    0,
                    0.0,
                    False,
                ):
                    merged_page_image[key] = existing_page_image.get(key)
            merged["page_image"] = merged_page_image
        elif existing_page_image:
            merged["page_image"] = dict(existing_page_image)

        rebuilt_evidence_map = [
            dict(row)
            for row in list((rebuilt_grounding or {}).get("evidence_map") or [])
            if isinstance(row, Mapping)
        ]
        if rebuilt_evidence_map:
            merged["evidence_map"] = rebuilt_evidence_map
        else:
            merged["evidence_map"] = [
                dict(row)
                for row in list((existing_grounding or {}).get("evidence_map") or [])
                if isinstance(row, Mapping)
            ]

        existing_atoms_by_id: Dict[str, Dict[str, Any]] = {}
        for atom in list((existing_grounding or {}).get("layout_atoms") or []):
            if not isinstance(atom, Mapping):
                continue
            layout_id = str(atom.get("layout_id") or "").strip()
            if layout_id:
                existing_atoms_by_id[layout_id] = dict(atom)

        merged_atoms: List[Dict[str, Any]] = []
        rebuilt_atoms = [
            dict(raw_atom)
            for raw_atom in list((rebuilt_grounding or {}).get("layout_atoms") or [])
            if isinstance(raw_atom, Mapping)
        ]
        if not rebuilt_atoms:
            rebuilt_atoms = [
                dict(raw_atom)
                for raw_atom in list((existing_grounding or {}).get("layout_atoms") or [])
                if isinstance(raw_atom, Mapping)
            ]
        for raw_atom in rebuilt_atoms:
            if not isinstance(raw_atom, Mapping):
                continue
            atom = dict(raw_atom)
            existing_atom = existing_atoms_by_id.get(str(atom.get("layout_id") or "").strip()) or {}
            for field in (
                "normalized_text",
                "normalization_reason",
                "normalization_mode",
                "normalization_confidence",
            ):
                if field in existing_atom and existing_atom.get(field) not in (None, ""):
                    atom[field] = existing_atom.get(field)
            merged_atoms.append(atom)
        merged["layout_atoms"] = merged_atoms

        atom_text_by_id = {
            str(atom.get("layout_id") or "").strip(): str(atom.get("normalized_text") or "").strip()
            for atom in merged_atoms
            if str(atom.get("layout_id") or "").strip()
        }
        atom_meta_by_id = {
            str(atom.get("layout_id") or "").strip(): {
                "reason": str(atom.get("normalization_reason") or "").strip(),
                "mode": str(atom.get("normalization_mode") or "").strip(),
                "confidence": atom.get("normalization_confidence"),
            }
            for atom in merged_atoms
            if str(atom.get("layout_id") or "").strip()
        }

        existing_nodes_by_source_ids: Dict[Tuple[str, ...], Dict[str, Any]] = {}
        for node in list((existing_grounding or {}).get("reading_nodes") or []):
            if not isinstance(node, Mapping):
                continue
            key = tuple(
                str(item).strip()
                for item in list(node.get("source_layout_ids") or [])
                if str(item).strip()
            )
            if key:
                existing_nodes_by_source_ids[key] = dict(node)

        merged_nodes: List[Dict[str, Any]] = []
        rebuilt_nodes = [
            dict(raw_node)
            for raw_node in list((rebuilt_grounding or {}).get("reading_nodes") or [])
            if isinstance(raw_node, Mapping)
        ]
        if not rebuilt_nodes:
            rebuilt_nodes = [
                dict(raw_node)
                for raw_node in list((existing_grounding or {}).get("reading_nodes") or [])
                if isinstance(raw_node, Mapping)
            ]
        for raw_node in rebuilt_nodes:
            if not isinstance(raw_node, Mapping):
                continue
            node = dict(raw_node)
            source_layout_ids = [
                str(item).strip()
                for item in list(node.get("source_layout_ids") or [])
                if str(item).strip()
            ]
            existing_node = existing_nodes_by_source_ids.get(tuple(source_layout_ids)) or {}
            if existing_node:
                for field in (
                    "normalized_text",
                    "normalization_reason",
                    "normalization_mode",
                    "normalization_confidence",
                ):
                    if field in existing_node and existing_node.get(field) not in (None, ""):
                        node[field] = existing_node.get(field)
            if not str(node.get("normalized_text") or "").strip() and source_layout_ids:
                normalized_parts = [
                    atom_text_by_id.get(layout_id, "").strip()
                    for layout_id in source_layout_ids
                    if atom_text_by_id.get(layout_id, "").strip()
                ]
                if normalized_parts:
                    node["normalized_text"] = "\n\n".join(normalized_parts).strip()
                    primary_layout_id = source_layout_ids[0]
                    node_meta = atom_meta_by_id.get(primary_layout_id) or {}
                    node["normalization_reason"] = str(node_meta.get("reason") or "").strip()
                    node["normalization_mode"] = str(node_meta.get("mode") or "").strip()
                    node["normalization_confidence"] = node_meta.get("confidence")
            merged_nodes.append(node)
        merged["reading_nodes"] = merged_nodes

        merged_meta = {
            **dict((existing_grounding or {}).get("meta") or {}),
            **dict(merged.get("meta") or {}),
        }
        normalization_summary = self._build_grounding_normalization_summary(merged_atoms)
        if normalization_summary:
            merged_meta["normalization_summary"] = normalization_summary
        merged["meta"] = merged_meta
        return merged

    def _backfill_grounding_text_normalizations_from_payload(
        self,
        *,
        payload: Mapping[str, Any],
        grounding: Mapping[str, Any],
    ) -> Dict[str, Any]:
        current_grounding = dict(grounding or {})
        current_summary = dict((current_grounding.get("meta") or {}).get("normalization_summary") or {})
        if int(current_summary.get("item_count") or 0) > 0:
            return current_grounding
        text_normalizations = dict(((payload or {}).get("layout_advice_v3") or {}).get("text_normalizations") or {})
        normalization_plan = dict(text_normalizations.get("normalization_plan") or {})
        if not list(normalization_plan.get("items") or []):
            return current_grounding
        return self._apply_layout_uid_text_normalization_to_grounding(
            grounding=current_grounding,
            normalization_plan=normalization_plan,
        )

    @staticmethod
    def _layout_uid_table_logical_row_system_prompt() -> str:
        return (
            "You refine a single table for the /read reader. "
            "DocMind already provides geometry truth and physical rows. "
            "Your job is ONLY to group physical rows into logical rows. "
            "Never rewrite cell text, never invent cells, never modify geometry, and never invent row indices. "
            "Use the attached page image only as visual reference for whether adjacent physical rows belong to the same logical benchmark row. "
            "Each physical row index must be assigned exactly once. "
            "Important patterns: multi-line headers should usually become one logical header row; "
            "a value row and its uncertainty row `(±...)` usually belong to the same logical data row; "
            "a blank first-column continuation row that continues benchmark values from the row above should usually be merged upward; "
            "rows with a benchmark label in the first column usually start a new logical row. "
            "Return JSON with status and step_result. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{\"logical_rows\":["
            "{\"logical_row_id\":\"lr1\",\"row_role\":\"header\",\"source_row_indices\":[0,1],\"rationale\":\"multi_line_header\"},"
            "{\"logical_row_id\":\"lr2\",\"row_role\":\"data\",\"source_row_indices\":[2,3],\"rationale\":\"value_plus_uncertainty\"}"
            "],\"notes\":[\"...\"]}}"
        )

    @staticmethod
    def _layout_uid_equation_normalization_system_prompt() -> str:
        return (
            "You normalize a single formula-like layout for the /read reader. "
            "DocMind geometry and evidence are already fixed. "
            "Use the attached page image and the provided layout/style hints only to improve display-layer readability. "
            "Never change layout_id, ownership, geometry, source ids, or evidence. "
            "Return JSON with status and step_result. "
            "If the OCR text is too unreliable, return empty normalized_latex and explain why. "
            "Prefer concise normalized_text and normalized_latex that preserve the source language and symbols. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{"
            "\"normalized_text\":\"...\","
            "\"normalized_latex\":\"...\","
            "\"reason\":\"...\","
            "\"confidence\":0.82,"
            "\"mode\":\"latex_reconstructed\","
            "\"notes\":[\"...\"]"
            "}}"
        )

    @staticmethod
    def _looks_like_numeric_table_cell(value: str) -> bool:
        text = str(value or "").strip()
        if not text:
            return False
        return bool(
            re.fullmatch(r"[-+±]?\d+(?:\.\d+)?%?", text)
            or re.fullmatch(r"\(±?\d+(?:\.\d+)?\)", text)
            or re.fullmatch(r"\d+(?:\.\d+)?", text)
        )

    @staticmethod
    def _looks_like_uncertainty_table_cell(value: str) -> bool:
        text = str(value or "").strip()
        if not text:
            return False
        return bool(re.fullmatch(r"\(±?\d+(?:\.\d+)?\)", text) or "±" in text)

    def _build_layout_uid_table_physical_row_hints(
        self,
        *,
        row_index: int,
        cells: Sequence[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        normalized_cells = [dict(cell) for cell in list(cells or []) if isinstance(cell, Mapping)]
        first_col_text = ""
        if normalized_cells:
            first_cell = min(normalized_cells, key=lambda item: (int(item.get("col_start") or 0), int(item.get("cell_id") or 0)))
            if int(first_cell.get("col_start") or 0) == 0:
                first_col_text = self._normalize_spaces(str(first_cell.get("text") or ""))
        texts = [self._normalize_spaces(str(cell.get("text") or "")) for cell in normalized_cells]
        non_empty_texts = [text for text in texts if text]
        non_empty_col_starts = sorted(
            {
                int(cell.get("col_start") or 0)
                for cell in normalized_cells
                if self._normalize_spaces(str(cell.get("text") or ""))
            }
        )
        uncertainty_like_count = sum(1 for text in non_empty_texts if self._looks_like_uncertainty_table_cell(text))
        numeric_like_count = sum(1 for text in non_empty_texts if self._looks_like_numeric_table_cell(text))
        return {
            "row_index": int(row_index),
            "first_col_text": first_col_text,
            "blank_first_column": not bool(first_col_text),
            "non_empty_col_starts": non_empty_col_starts,
            "numeric_like_count": int(numeric_like_count),
            "uncertainty_like_count": int(uncertainty_like_count),
            "contains_pm": any("±" in text for text in non_empty_texts),
            "looks_like_uncertainty_row": bool(
                non_empty_texts
                and uncertainty_like_count >= max(1, len(non_empty_texts) // 2)
                and not first_col_text
            ),
        }

    def _build_layout_uid_table_physical_rows(
        self,
        table_cells: Sequence[Mapping[str, Any]],
    ) -> List[Dict[str, Any]]:
        rows_map: Dict[int, List[Dict[str, Any]]] = {}
        for raw_cell in list(table_cells or []):
            if not isinstance(raw_cell, Mapping):
                continue
            row_start = max(0, int(raw_cell.get("row_start") or 0))
            cell = {
                "cell_id": int(raw_cell.get("cell_id") or 0),
                "row_start": row_start,
                "row_end": max(row_start, int(raw_cell.get("row_end") or row_start)),
                "col_start": max(0, int(raw_cell.get("col_start") or 0)),
                "col_end": max(0, int(raw_cell.get("col_end") or raw_cell.get("col_start") or 0)),
                "text": LiteratureReaderComposeService._normalize_spaces(str(raw_cell.get("text") or "")),
                "layout_ids": [
                    str(item).strip()
                    for item in list(raw_cell.get("layout_ids") or [])
                    if str(item).strip()
                ],
            }
            rows_map.setdefault(row_start, []).append(cell)
        physical_rows: List[Dict[str, Any]] = []
        for row_index in sorted(rows_map.keys()):
            cells = sorted(
                rows_map[row_index],
                key=lambda item: (int(item.get("col_start") or 0), int(item.get("cell_id") or 0)),
            )
            physical_rows.append(
                {
                    "row_index": int(row_index),
                    "cells": cells,
                    "hints": self._build_layout_uid_table_physical_row_hints(row_index=row_index, cells=cells),
                }
            )
        return physical_rows

    def _build_layout_uid_table_logical_row_prompt_payload(
        self,
        *,
        page: int,
        title: str,
        caption: str,
        table_cells: Sequence[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        physical_rows = self._build_layout_uid_table_physical_rows(table_cells)
        return {
            "page_meta": {
                "page": int(page),
                "reader_mode": "read_layout_uid_v1_table_logical_rows",
            },
            "table_meta": {
                "title": str(title or "").strip(),
                "caption": str(caption or "").strip(),
                "cell_count": len(list(table_cells or [])),
                "physical_row_count": len(physical_rows),
            },
            "physical_rows": physical_rows,
            "rules": {
                "task": "group_physical_rows_into_logical_rows",
                "preserve_row_order": True,
                "exactly_once_assignment": True,
                "forbid_text_rewrite": True,
                "forbid_geometry_mutation": True,
                "allowed_row_roles": ["header", "data", "note"],
                "common_patterns": [
                    "multi_line_header",
                    "value_plus_uncertainty",
                    "blank_first_column_continuation",
                ],
            },
        }

    def _normalize_layout_uid_table_logical_row_plan(
        self,
        *,
        physical_rows: Sequence[Mapping[str, Any]],
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        known_indices = [int(row.get("row_index") or 0) for row in list(physical_rows or []) if isinstance(row, Mapping)]
        known_set = set(known_indices)
        normalized_rows: List[Dict[str, Any]] = []
        used_indices: List[int] = []
        errors: List[str] = []
        for raw_row in list((step_result or {}).get("logical_rows") or (step_result or {}).get("rows") or []):
            if not isinstance(raw_row, Mapping):
                continue
            source_row_indices = []
            for item in list(raw_row.get("source_row_indices") or []):
                try:
                    source_row_indices.append(int(item))
                except Exception:
                    continue
            source_row_indices = list(dict.fromkeys(source_row_indices))
            if not source_row_indices:
                continue
            unknown = [row_index for row_index in source_row_indices if row_index not in known_set]
            if unknown:
                errors.extend([f"unknown_physical_row:{row_index}" for row_index in unknown])
                continue
            row_role = str(raw_row.get("row_role") or raw_row.get("role") or "").strip().lower() or "data"
            if row_role not in {"header", "data", "note"}:
                errors.append(f"invalid_row_role:{row_role}")
                row_role = "data"
            normalized_rows.append(
                {
                    "logical_row_id": str(raw_row.get("logical_row_id") or f"lr{len(normalized_rows) + 1}").strip()
                    or f"lr{len(normalized_rows) + 1}",
                    "row_role": row_role,
                    "source_row_indices": sorted(source_row_indices),
                    "rationale": str(raw_row.get("rationale") or "").strip(),
                }
            )
            used_indices.extend(source_row_indices)
        duplicates = sorted({row_index for row_index in used_indices if used_indices.count(row_index) > 1})
        if duplicates:
            errors.extend([f"duplicate_physical_row:{row_index}" for row_index in duplicates])
        missing = [row_index for row_index in known_indices if row_index not in set(used_indices)]
        if missing:
            errors.extend([f"missing_physical_row:{row_index}" for row_index in missing])
        if errors or not normalized_rows:
            fallback_rows = [
                {
                    "logical_row_id": f"lr{index + 1}",
                    "row_role": "data",
                    "source_row_indices": [int(row_index)],
                    "rationale": "deterministic_physical_row_fallback",
                }
                for index, row_index in enumerate(sorted(known_indices))
            ]
            return {
                "logical_rows": fallback_rows,
                "notes": ["deterministic_table_logical_row_fallback"],
            }, {
                "passed": False,
                "errors": errors or ["empty_logical_rows"],
                "fallback_used": True,
            }
        normalized_rows = sorted(
            normalized_rows,
            key=lambda row: min(int(item) for item in list(row.get("source_row_indices") or [10**9])),
        )
        return {
            "logical_rows": normalized_rows,
            "notes": [
                str(item).strip()
                for item in list((step_result or {}).get("notes") or [])
                if str(item).strip()
            ],
        }, {
            "passed": True,
            "errors": [],
            "fallback_used": False,
        }

    def _build_layout_uid_equation_normalization_prompt_payload(
        self,
        *,
        page: int,
        group_id: str,
        atoms: Sequence[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        compact_atoms: List[Dict[str, Any]] = []
        for atom in list(atoms or []):
            if not isinstance(atom, Mapping):
                continue
            compact_atoms.append(
                {
                    "layout_id": str(atom.get("layout_id") or "").strip(),
                    "layout_type": str(atom.get("layout_type") or "").strip().lower(),
                    "layout_sub_type": str(atom.get("layout_sub_type") or "").strip().lower(),
                    "raw_text": str(atom.get("raw_text") or "").strip(),
                    "clean_text": str(atom.get("clean_text") or "").strip(),
                    "alignment": str(atom.get("alignment") or "").strip().lower(),
                    "line_height": float(atom.get("line_height") or 0.0),
                    "layout_pos": list(atom.get("layout_pos") or []),
                    "blocks": [
                        {
                            "text": str(block.get("text") or "").strip(),
                            "style_id": int(block.get("style_id") or 0),
                            "pos": list(block.get("pos") or []),
                        }
                        for block in list(atom.get("blocks") or [])
                        if isinstance(block, Mapping)
                    ],
                }
            )
        transcript_parts = [
            self._normalize_spaces(str(atom.get("clean_text") or atom.get("raw_text") or ""))
            for atom in compact_atoms
            if self._normalize_spaces(str(atom.get("clean_text") or atom.get("raw_text") or ""))
        ]
        return {
            "page_meta": {
                "page": int(page),
                "reader_mode": "read_layout_uid_v1_equation_normalization",
                "group_id": str(group_id or "").strip(),
            },
            "equation": {
                "layout_count": len(compact_atoms),
                "transcript": " ".join(transcript_parts).strip(),
                "atoms": compact_atoms,
            },
            "rules": {
                "task": "normalize_formula_display_text",
                "preserve_geometry": True,
                "preserve_source_ids": True,
                "forbid_translation": True,
                "forbid_evidence_rewrite": True,
                "allow_empty_normalized_latex": True,
            },
        }

    def _build_layout_uid_figure_insight_prompt_payload(
        self,
        *,
        page: int,
        group_id: str,
        atoms: Sequence[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        compact_atoms: List[Dict[str, Any]] = []
        caption_parts: List[str] = []
        focus_bboxes: List[Tuple[float, float, float, float]] = []
        for atom in list(atoms or []):
            if not isinstance(atom, Mapping):
                continue
            node_kind = str(atom.get("node_kind") or "").strip().lower()
            raw_text = str(atom.get("raw_text") or "").strip()
            clean_text = str(atom.get("clean_text") or "").strip()
            if node_kind != "figure" and (clean_text or raw_text):
                caption_parts.append(clean_text or raw_text)
            layout_pos = list(atom.get("layout_pos") or [])
            bbox = self._bbox_from_docmind_pos(layout_pos)
            if bbox is not None and node_kind == "figure":
                focus_bboxes.append(tuple(float(value) for value in bbox))
            compact_atoms.append(
                {
                    "layout_id": str(atom.get("layout_id") or "").strip(),
                    "node_kind": node_kind,
                    "layout_type": str(atom.get("layout_type") or "").strip().lower(),
                    "layout_sub_type": str(atom.get("layout_sub_type") or "").strip().lower(),
                    "raw_text": raw_text,
                    "clean_text": clean_text,
                    "layout_pos": layout_pos,
                    "blocks": [
                        {
                            "text": str(block.get("text") or "").strip(),
                            "style_id": int(block.get("style_id") or 0),
                            "pos": list(block.get("pos") or []),
                        }
                        for block in list(atom.get("blocks") or [])
                        if isinstance(block, Mapping)
                    ],
                }
            )
        caption = self._strip_leading_figure_caption_noise(" ".join(part for part in caption_parts if part).strip())
        source_label = ""
        if caption:
            label_match = re.match(r"^(Fig(?:ure)?\.?\s*\d+[A-Za-z]?)", caption, flags=re.IGNORECASE)
            if label_match:
                source_label = self._normalize_spaces(str(label_match.group(1) or ""))
        focus_bbox = {}
        if focus_bboxes:
            focus_bbox = {
                "x0": min(item[0] for item in focus_bboxes),
                "top": min(item[1] for item in focus_bboxes),
                "x1": max(item[2] for item in focus_bboxes),
                "bottom": max(item[3] for item in focus_bboxes),
            }
        return {
            "page_meta": {
                "page": int(page),
                "reader_mode": "read_layout_uid_v1_figure_insight",
                "group_id": str(group_id or "").strip(),
            },
            "figure": {
                "caption": caption,
                "source_label": source_label,
                "focus_bbox": focus_bbox,
                "layout_count": len(compact_atoms),
                "atoms": compact_atoms,
            },
            "rules": {
                "task": "explain_figure_for_read",
                "preserve_geometry": True,
                "preserve_source_ids": True,
                "forbid_caption_rewrite": True,
                "output_language": "zh-CN",
                "insight_must_be_image_grounded": True,
                "insight_should_be_brief": True,
            },
        }

    @staticmethod
    def _layout_uid_figure_insight_system_prompt() -> str:
        return (
            "You explain a single figure group for the /read reader. "
            "Use the attached page image as the primary visual reference and the focus_bbox/caption only as grounding hints. "
            "Write one concise Chinese insight sentence that helps a reader understand what the figure is showing. "
            "Do not simply restate the caption, do not invent evidence, and do not modify caption/source ids/geometry. "
            "If the visible figure content is too unclear, return an empty insight. "
            "Return JSON with status and step_result. "
            "Output format: "
            "{\"status\":\"done\",\"step_result\":{\"insight\":\"...\",\"reason\":\"...\",\"confidence\":0.84,\"mode\":\"image_grounded_summary\",\"notes\":[\"...\"]}}"
        )

    def _normalize_layout_uid_figure_refinement(
        self,
        *,
        atoms: Sequence[Mapping[str, Any]],
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        caption_parts = [
            self._strip_leading_figure_caption_noise(
                str(atom.get("clean_text") or atom.get("raw_text") or "").strip()
            )
            for atom in list(atoms or [])
            if isinstance(atom, Mapping) and str(atom.get("node_kind") or "").strip().lower() != "figure"
        ]
        caption = " ".join(part for part in caption_parts if part).strip()
        insight = self._normalize_spaces(
            str((step_result or {}).get("insight") or (step_result or {}).get("ai_insight") or "")
        )
        reason = self._normalize_spaces(str((step_result or {}).get("reason") or ""))
        mode = self._normalize_spaces(str((step_result or {}).get("mode") or "")) or "image_grounded_summary"
        notes = [
            self._normalize_spaces(str(item))
            for item in list((step_result or {}).get("notes") or [])
            if self._normalize_spaces(str(item))
        ]
        errors: List[str] = []
        raw_confidence = (step_result or {}).get("confidence")
        try:
            confidence_value = float(raw_confidence)
        except Exception:
            confidence_value = 0.0
            if raw_confidence is not None:
                errors.append("invalid_confidence")
        confidence_value = max(0.0, min(1.0, confidence_value))
        if len(insight) > 220:
            errors.append("insight_too_long")
            insight = ""
        if caption and insight and insight == caption:
            errors.append("insight_duplicates_caption")
            insight = ""
        if not insight:
            return {
                "ai_insight": "",
                "reason": "",
                "confidence": 0.0,
                "mode": "",
                "notes": notes,
            }, {
                "passed": False,
                "errors": errors or ["empty_insight"],
                "fallback_used": True,
            }
        return {
            "ai_insight": insight,
            "reason": reason,
            "confidence": confidence_value,
            "mode": mode,
            "notes": notes,
        }, {
            "passed": not bool(errors),
            "errors": errors,
            "fallback_used": False,
        }

    def _normalize_layout_uid_equation_refinement(
        self,
        *,
        atoms: Sequence[Mapping[str, Any]],
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        transcript_parts = [
            self._normalize_spaces(str(atom.get("clean_text") or atom.get("raw_text") or ""))
            for atom in list(atoms or [])
            if isinstance(atom, Mapping)
        ]
        transcript = " ".join([part for part in transcript_parts if part]).strip()
        normalized_text = self._normalize_spaces(str((step_result or {}).get("normalized_text") or ""))
        normalized_latex = str((step_result or {}).get("normalized_latex") or "").strip()
        reason = self._normalize_spaces(str((step_result or {}).get("reason") or ""))
        mode = self._normalize_spaces(str((step_result or {}).get("mode") or "")) or "display_normalized"
        notes = [
            self._normalize_spaces(str(item))
            for item in list((step_result or {}).get("notes") or [])
            if self._normalize_spaces(str(item))
        ]
        errors: List[str] = []
        confidence_value = 0.0
        raw_confidence = (step_result or {}).get("confidence")
        try:
            confidence_value = float(raw_confidence)
        except Exception:
            confidence_value = 0.0
            if raw_confidence is not None:
                errors.append("invalid_confidence")
        confidence_value = max(0.0, min(1.0, confidence_value))
        if normalized_latex and len(normalized_latex) > 800:
            errors.append("normalized_latex_too_long")
            normalized_latex = ""
        if normalized_text and len(normalized_text) > 800:
            errors.append("normalized_text_too_long")
            normalized_text = ""
        if normalized_latex and "\n\n" in normalized_latex:
            normalized_latex = normalized_latex.replace("\n\n", "\n").strip()
        if normalized_text and transcript and normalized_text == transcript:
            normalized_text = ""
        if not normalized_text and normalized_latex:
            normalized_text = normalized_latex
        if not normalized_text and not normalized_latex:
            return {
                "normalized_text": "",
                "normalized_latex": "",
                "reason": "",
                "confidence": 0.0,
                "mode": "",
                "notes": notes,
            }, {
                "passed": False,
                "errors": errors or ["empty_normalization"],
                "fallback_used": True,
            }
        return {
            "normalized_text": normalized_text,
            "normalized_latex": normalized_latex,
            "reason": reason,
            "confidence": confidence_value,
            "mode": mode,
            "notes": notes,
        }, {
            "passed": not bool(errors),
            "errors": errors,
            "fallback_used": False,
        }

    @staticmethod
    def _looks_like_table_caption_text(text: str) -> bool:
        normalized = str(text or "").strip()
        if not normalized:
            return False
        return bool(re.match(r"^table\s*\d+[a-z]?(?:[\s:.\-]|$)", normalized, flags=re.IGNORECASE))

    @staticmethod
    def _looks_like_quantization_config_text(text: str) -> bool:
        normalized = str(text or "").strip()
        if not normalized:
            return False
        lowered = normalized.lower()
        bullet_or_enumerated = bool(re.match(r"^(?:[•·\-*]\s*|\d+\.\s*)", normalized))
        quantization_token_count = len(
            re.findall(
                r"\b(?:fp8|bf16|q\d(?:[._-]?[a-z0-9]+)*|\d-bit|llama\.cpp\d*|unsloth\d*|tencent api|reported|ours)\b",
                lowered,
            )
        )
        if quantization_token_count == 0:
            return False
        if bullet_or_enumerated:
            return True
        if ":" in normalized or " for " in lowered:
            return True
        return False

    @classmethod
    def _looks_like_equation_text(cls, text: str) -> bool:
        normalized = str(text or "").strip()
        if not normalized:
            return False
        lowered = normalized.lower()
        if cls._looks_like_quantization_config_text(normalized):
            return False
        if any(
            token in lowered
            for token in (
                "\\frac",
                "\\sum",
                "\\int",
                "\\alpha",
                "\\beta",
                "\\gamma",
                "\\lambda",
                "\\theta",
                "\\begin{",
                "\\end{",
                "\\left",
                "\\right",
                "\\mathrm",
            )
        ):
            return True
        if normalized.startswith("$$") or normalized.startswith("\\(") or normalized.startswith("\\["):
            return True
        math_symbol_count = len(re.findall(r"[=+*/^≤≥≈∑∫√±×÷]", normalized))
        alpha_token_count = len(re.findall(r"[A-Za-z]{2,}", normalized))
        if math_symbol_count >= 2 and alpha_token_count <= 10 and len(normalized) <= 240:
            return True
        if re.search(r"\b[A-Za-z]\s*=\s*[^=]", normalized) and len(normalized) <= 240:
            return True
        return False

    @staticmethod
    def _merge_layout_uid_table_cell_text(base: str, extra: str) -> str:
        lines = [
            *[item.strip() for item in str(base or "").split("\n") if item.strip()],
            *[item.strip() for item in str(extra or "").split("\n") if item.strip()],
        ]
        if not lines:
            return ""
        return "\n".join(list(dict.fromkeys(lines)))

    def _materialize_layout_uid_logical_table_rows(
        self,
        *,
        normalized_cells: Sequence[Mapping[str, Any]],
        logical_row_plan: Mapping[str, Any],
    ) -> Tuple[List[Dict[str, Any]], int]:
        physical_rows: Dict[int, List[Dict[str, Any]]] = {}
        for raw_cell in list(normalized_cells or []):
            if not isinstance(raw_cell, Mapping):
                continue
            row_start = max(0, int(raw_cell.get("row_start") or 0))
            physical_rows.setdefault(row_start, []).append(dict(raw_cell))

        physical_to_logical: Dict[int, int] = {}
        logical_rows: List[Dict[str, Any]] = []
        for logical_index, raw_row in enumerate(list((logical_row_plan or {}).get("logical_rows") or [])):
            if not isinstance(raw_row, Mapping):
                continue
            source_row_indices = [
                int(item)
                for item in list(raw_row.get("source_row_indices") or [])
                if isinstance(item, int) or str(item).strip().isdigit()
            ]
            merged_cells: List[Dict[str, Any]] = []
            for row_index in source_row_indices:
                physical_to_logical[int(row_index)] = logical_index
                row_cells = sorted(
                    [dict(cell) for cell in list(physical_rows.get(int(row_index)) or [])],
                    key=lambda item: (int(item.get("col_start") or 0), int(item.get("cell_id") or 0)),
                )
                for cell in row_cells:
                    existing = next(
                        (
                            item
                            for item in merged_cells
                            if int(item.get("col_start") or 0) == int(cell.get("col_start") or 0)
                            and int(item.get("col_end") or 0) == int(cell.get("col_end") or 0)
                        ),
                        None,
                    )
                    if existing is None:
                        merged_cells.append(dict(cell))
                        continue
                    existing["text"] = self._merge_layout_uid_table_cell_text(
                        str(existing.get("text") or ""),
                        str(cell.get("text") or ""),
                    )
                    existing["layout_ids"] = list(
                        dict.fromkeys(
                            [
                                *[str(item).strip() for item in list(existing.get("layout_ids") or []) if str(item).strip()],
                                *[str(item).strip() for item in list(cell.get("layout_ids") or []) if str(item).strip()],
                            ]
                        )
                    )
                    existing["row_end"] = max(
                        int(existing.get("row_end") or existing.get("row_start") or 0),
                        int(cell.get("row_end") or cell.get("row_start") or 0),
                    )
                    existing["rowspan"] = max(
                        int(existing.get("rowspan") or 1),
                        int(cell.get("rowspan") or 1),
                    )
                    for key in ("x0", "y0"):
                        existing_value = existing.get(key)
                        new_value = cell.get(key)
                        if existing_value is None:
                            existing[key] = new_value
                        elif new_value is not None:
                            existing[key] = min(float(existing_value), float(new_value))
                    for key in ("x1", "y1"):
                        existing_value = existing.get(key)
                        new_value = cell.get(key)
                        if existing_value is None:
                            existing[key] = new_value
                        elif new_value is not None:
                            existing[key] = max(float(existing_value), float(new_value))
            merged_cells = sorted(
                merged_cells,
                key=lambda item: (int(item.get("col_start") or 0), int(item.get("cell_id") or 0)),
            )
            logical_rows.append(
                {
                    "row_index": int(logical_index),
                    "row_role": str(raw_row.get("row_role") or "data").strip() or "data",
                    "source_row_indices": source_row_indices,
                    "cells": merged_cells,
                }
            )

        logical_rows = self._normalize_layout_uid_logical_row_pairs(logical_rows)

        for logical_index, logical_row in enumerate(logical_rows):
            logical_row["row_index"] = int(logical_index)
            for cell in list(logical_row.get("cells") or []):
                physical_row_start = int(cell.get("row_start") or 0)
                physical_row_end = int(cell.get("row_end") or physical_row_start)
                logical_row_start = physical_to_logical.get(physical_row_start, logical_index)
                logical_row_end = physical_to_logical.get(physical_row_end, logical_row_start)
                cell["row_start"] = int(logical_row_start)
                cell["row_end"] = int(logical_row_end)
                cell["rowspan"] = max(1, int(logical_row_end) - int(logical_row_start) + 1)

        logical_header_row_count = 0
        for row in logical_rows:
            if str(row.get("row_role") or "").strip().lower() == "header":
                logical_header_row_count += 1
            else:
                break
        return logical_rows, int(logical_header_row_count)

    def _normalize_layout_uid_logical_row_pairs(
        self,
        logical_rows: Sequence[Mapping[str, Any]],
    ) -> List[Dict[str, Any]]:
        normalized_rows: List[Dict[str, Any]] = []

        def _cells_by_column(cells: Sequence[Mapping[str, Any]]) -> Dict[int, Dict[str, Any]]:
            return {
                int(cell.get("col_start") or 0): dict(cell)
                for cell in list(cells or [])
                if isinstance(cell, Mapping)
            }

        def _merge_rows(previous: Dict[str, Any], current: Dict[str, Any]) -> Dict[str, Any]:
            previous_cells = [dict(cell) for cell in list(previous.get("cells") or []) if isinstance(cell, Mapping)]
            previous_by_col = {int(cell.get("col_start") or 0): cell for cell in previous_cells}
            current_cells = sorted(
                [dict(cell) for cell in list(current.get("cells") or []) if isinstance(cell, Mapping)],
                key=lambda item: (int(item.get("col_start") or 0), int(item.get("cell_id") or 0)),
            )

            for cell in current_cells:
                col_start = int(cell.get("col_start") or 0)
                existing = previous_by_col.get(col_start)
                if existing is None:
                    previous_cells.append(dict(cell))
                    previous_by_col[col_start] = previous_cells[-1]
                    continue
                existing_text = self._normalize_spaces(str(existing.get("text") or ""))
                incoming_text = self._normalize_spaces(str(cell.get("text") or ""))
                if incoming_text and incoming_text != existing_text:
                    existing["text"] = self._merge_layout_uid_table_cell_text(existing_text, incoming_text)
                existing["layout_ids"] = list(
                    dict.fromkeys(
                        [
                            *[str(item).strip() for item in list(existing.get("layout_ids") or []) if str(item).strip()],
                            *[str(item).strip() for item in list(cell.get("layout_ids") or []) if str(item).strip()],
                        ]
                    )
                )
                for key in ("x0", "y0"):
                    existing_value = existing.get(key)
                    incoming_value = cell.get(key)
                    if incoming_value is None:
                        continue
                    if existing_value is None:
                        existing[key] = incoming_value
                    else:
                        existing[key] = min(float(existing_value), float(incoming_value))
                for key in ("x1", "y1"):
                    existing_value = existing.get(key)
                    incoming_value = cell.get(key)
                    if incoming_value is None:
                        continue
                    if existing_value is None:
                        existing[key] = incoming_value
                    else:
                        existing[key] = max(float(existing_value), float(incoming_value))

            previous["cells"] = sorted(
                previous_cells,
                key=lambda item: (int(item.get("col_start") or 0), int(item.get("cell_id") or 0)),
            )
            previous["source_row_indices"] = sorted(
                {
                    int(item)
                    for item in [
                        *list(previous.get("source_row_indices") or []),
                        *list(current.get("source_row_indices") or []),
                    ]
                    if isinstance(item, int) or str(item).strip().isdigit()
                }
            )
            return previous

        def _should_merge(previous: Dict[str, Any], current: Dict[str, Any]) -> bool:
            if str(previous.get("row_role") or "").strip().lower() != "data":
                return False
            if str(current.get("row_role") or "").strip().lower() != "data":
                return False

            previous_by_col = _cells_by_column(previous.get("cells") or [])
            current_by_col = _cells_by_column(current.get("cells") or [])
            previous_label = self._normalize_spaces(str((previous_by_col.get(0) or {}).get("text") or ""))
            current_label = self._normalize_spaces(str((current_by_col.get(0) or {}).get("text") or ""))
            previous_first_metric = self._normalize_spaces(str((previous_by_col.get(1) or {}).get("text") or ""))
            current_first_metric = self._normalize_spaces(str((current_by_col.get(1) or {}).get("text") or ""))

            previous_numeric_cols = {
                col_start
                for col_start, cell in previous_by_col.items()
                if col_start > 0
                and self._looks_like_numeric_table_cell(str(cell.get("text") or ""))
                and not self._looks_like_uncertainty_table_cell(str(cell.get("text") or ""))
            }
            current_uncertainty_cols = {
                col_start
                for col_start, cell in current_by_col.items()
                if col_start > 0 and self._looks_like_uncertainty_table_cell(str(cell.get("text") or ""))
            }
            if not previous_numeric_cols or not current_uncertainty_cols:
                return False

            overlap = previous_numeric_cols & current_uncertainty_cols
            if len(overlap) < max(2, len(current_uncertainty_cols) // 2):
                return False

            previous_blank_lead = not previous_label and not previous_first_metric
            current_blank_lead = not current_label and not current_first_metric
            return previous_blank_lead or current_blank_lead

        for raw_row in list(logical_rows or []):
            if not isinstance(raw_row, Mapping):
                continue
            current = {
                "row_index": int(raw_row.get("row_index") or len(normalized_rows)),
                "row_role": str(raw_row.get("row_role") or "data").strip() or "data",
                "source_row_indices": [
                    int(item)
                    for item in list(raw_row.get("source_row_indices") or [])
                    if isinstance(item, int) or str(item).strip().isdigit()
                ],
                "cells": [dict(cell) for cell in list(raw_row.get("cells") or []) if isinstance(cell, Mapping)],
            }
            if normalized_rows and _should_merge(normalized_rows[-1], current):
                normalized_rows[-1] = _merge_rows(normalized_rows[-1], current)
                continue
            normalized_rows.append(current)

        return normalized_rows

    def _build_layout_uid_table_props(
        self,
        *,
        page: int,
        atoms: Sequence[Mapping[str, Any]],
        logical_row_plan: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        caption_texts: List[str] = []
        note_texts: List[str] = []
        markdown_lines: List[str] = []
        table_blocks: List[Dict[str, Any]] = []
        table_cells: List[Dict[str, Any]] = []
        table_layout_ids: List[str] = []
        fallback_canonical_block_ids: List[str] = []

        for atom in list(atoms or []):
            if not isinstance(atom, Mapping):
                continue
            atom_layout_id = str(atom.get("layout_id") or "").strip()
            node_kind = str(atom.get("node_kind") or "").strip().lower()
            clean_text = self._normalize_spaces(str(atom.get("clean_text") or atom.get("raw_text") or ""))
            if clean_text and ("|" in clean_text or "\t" in clean_text):
                for line in str(clean_text).splitlines():
                    normalized_line = self._normalize_spaces(line)
                    if normalized_line and ("|" in normalized_line or "\t" in normalized_line):
                        markdown_lines.append(normalized_line)
            if node_kind == "table_caption" or self._looks_like_table_caption_text(clean_text):
                if clean_text:
                    caption_texts.append(clean_text)
                continue
            if node_kind in {"metadata", "paragraph"} and clean_text and re.match(r"^(note|notes|abbrev(?:iation)?s?)\b", clean_text, flags=re.IGNORECASE):
                note_texts.append(clean_text)
                continue
            if node_kind != "table":
                continue
            if atom_layout_id and atom_layout_id not in table_layout_ids:
                table_layout_ids.append(atom_layout_id)
            for block_id in list(atom.get("canonical_block_ids") or []):
                normalized_block_id = str(block_id or "").strip()
                if normalized_block_id and normalized_block_id not in fallback_canonical_block_ids:
                    fallback_canonical_block_ids.append(normalized_block_id)
            for raw_cell in list(atom.get("table_cells") or []):
                if not isinstance(raw_cell, Mapping):
                    continue
                table_cells.append(dict(raw_cell))
            for block in list(atom.get("blocks") or []):
                if not isinstance(block, Mapping):
                    continue
                block_text = self._normalize_spaces(str(block.get("text") or ""))
                bbox = self._bbox_from_docmind_pos(list(block.get("pos") or []))
                if not block_text or bbox is None:
                    continue
                x0, top, x1, bottom = bbox
                table_blocks.append(
                    {
                        "text": block_text,
                        "x0": float(x0),
                        "x1": float(x1),
                        "top": float(top),
                        "bottom": float(bottom),
                    }
                )

        matrix: List[List[str]] = []
        header_row_count = 0
        raw_markdown = "\n".join(markdown_lines).strip()
        row_evidence: List[Dict[str, Any]] = []
        cell_evidence: List[Dict[str, Any]] = []

        def _build_row_anchor(*, row_index: int, row_cells: Sequence[Mapping[str, Any]]) -> Optional[Dict[str, Any]]:
            polygons: List[Dict[str, Any]] = []
            row_layout_ids: List[str] = []
            row_quote_parts: List[str] = []
            for cell in list(row_cells or []):
                cell_text = self._normalize_spaces(str(cell.get("text") or ""))
                if cell_text:
                    row_quote_parts.append(cell_text)
                for layout_id in list(cell.get("layout_ids") or []):
                    token = str(layout_id or "").strip()
                    if token and token not in row_layout_ids:
                        row_layout_ids.append(token)
                for poly_index, poly in enumerate(list(cell.get("polygons") or []), start=1):
                    points = self._normalize_grounding_points(poly)
                    if len(points) < 3:
                        continue
                    polygons.append(
                        {
                            "points": points,
                            "source": "page_grounding_v1",
                            "component_id": f"table_row_{row_index + 1}:{poly_index}",
                        }
                    )
            if not polygons:
                return None
            all_points = [
                point
                for poly in polygons
                for point in list(poly.get("points") or [])
                if isinstance(point, Mapping)
            ]
            xs = [float(point.get("x") or 0.0) for point in all_points]
            ys = [float(point.get("y") or 0.0) for point in all_points]
            if not xs or not ys:
                return None
            quote_text = " | ".join(part for part in row_quote_parts if part).strip()
            source_layout_id = table_layout_ids[0] if table_layout_ids else f"table_row_{row_index + 1}"
            anchor = {
                "page": int(page),
                "start_char": 0,
                "end_char": max(1, len(quote_text) or len(polygons)),
                "quote": quote_text or None,
                "quote_text": quote_text or None,
                "anchor_id": f"layout_uid_v1:{source_layout_id}:row:{row_index + 1}",
                "canonical_block_id": "",
                "source_layout_id": f"{source_layout_id}:row:{row_index + 1}",
                "coord_version": "layout_uid_v1",
                "anchor_confidence": 0.98,
                "bbox_hint": {
                    "x0": min(xs),
                    "x1": max(xs),
                    "top": min(ys),
                    "bottom": max(ys),
                    "page_width": None,
                    "page_height": None,
                },
                "geometry_version": "poly_v1",
                "geometry": {
                    "polygons": polygons,
                    "page_width": None,
                    "page_height": None,
                },
                "anchor_v2": {
                    "page": int(page),
                    "start_char": 0,
                    "end_char": max(1, len(quote_text) or len(polygons)),
                    "coord_version": "layout_uid_v1",
                    "canonical_block_id": "",
                },
                "segment_index": 0,
                "segment_total": 1,
                "source_word_ids": [],
                "source_char_ranges": [],
            }
            return {
                "row_index": int(row_index),
                "label": self._normalize_spaces(str(row_cells[0].get("text") or "")) or f"Row {row_index + 1}",
                "source_atom_ids": row_layout_ids,
                "anchor": anchor,
            }

        def _build_cell_anchor(*, cell: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
            points_sets = [self._normalize_grounding_points(poly) for poly in list(cell.get("polygons") or [])]
            points_sets = [points for points in points_sets if len(points) >= 3]
            if not points_sets:
                return None
            all_points = [point for points in points_sets for point in points]
            xs = [float(point.get("x") or 0.0) for point in all_points]
            ys = [float(point.get("y") or 0.0) for point in all_points]
            if not xs or not ys:
                return None
            quote_text = self._normalize_spaces(str(cell.get("text") or ""))
            source_layout_ids = [
                str(layout_id or "").strip()
                for layout_id in list(cell.get("layout_ids") or [])
                if str(layout_id or "").strip()
            ]
            source_layout_id = source_layout_ids[0] if source_layout_ids else ""
            polygons = [
                {
                    "points": points,
                    "source": "page_grounding_v1",
                    "component_id": f"{source_layout_id or 'table_cell'}:{index + 1}",
                }
                for index, points in enumerate(points_sets)
            ]
            anchor = {
                "page": int(page),
                "start_char": 0,
                "end_char": max(1, len(quote_text) or len(polygons)),
                "quote": quote_text or None,
                "quote_text": quote_text or None,
                "anchor_id": f"layout_uid_v1:{source_layout_id or 'table_cell'}:cell:{int(cell.get('cell_id') or 0)}",
                "canonical_block_id": "",
                "source_layout_id": source_layout_id or None,
                "coord_version": "layout_uid_v1",
                "anchor_confidence": 0.99,
                "bbox_hint": {
                    "x0": min(xs),
                    "x1": max(xs),
                    "top": min(ys),
                    "bottom": max(ys),
                    "page_width": None,
                    "page_height": None,
                },
                "geometry_version": "poly_v1",
                "geometry": {
                    "polygons": polygons,
                    "page_width": None,
                    "page_height": None,
                },
                "anchor_v2": {
                    "page": int(page),
                    "start_char": 0,
                    "end_char": max(1, len(quote_text) or len(polygons)),
                    "coord_version": "layout_uid_v1",
                    "canonical_block_id": "",
                },
                "segment_index": 0,
                "segment_total": 1,
                "source_word_ids": [],
                "source_char_ranges": [],
            }
            return {
                "cell_id": int(cell.get("cell_id") or 0),
                "row_start": int(cell.get("row_start") or 0),
                "col_start": int(cell.get("col_start") or 0),
                "label": quote_text or "Cell",
                "source_atom_ids": source_layout_ids,
                "anchor": anchor,
            }

        normalized_cells: List[Dict[str, Any]] = []
        column_widths: List[float] = []

        if table_cells:
            max_row = max(
                max(int(cell.get("row_start") or 0), int(cell.get("row_end") or 0))
                for cell in table_cells
            )
            max_col = max(
                max(int(cell.get("col_start") or 0), int(cell.get("col_end") or 0))
                for cell in table_cells
            )
            matrix = [[""] * (max_col + 1) for _ in range(max_row + 1)]
            row_cells_map: Dict[int, List[Dict[str, Any]]] = {}
            for cell in table_cells:
                row_start = max(0, int(cell.get("row_start") or 0))
                row_end = max(row_start, int(cell.get("row_end") or row_start))
                col_start = max(0, int(cell.get("col_start") or 0))
                cell_text = self._normalize_spaces(str(cell.get("text") or ""))
                cell_x0 = cell.get("x0")
                cell_x1 = cell.get("x1")
                cell_y0 = cell.get("y0")
                cell_y1 = cell.get("y1")
                if (
                    cell_x0 is None
                    or cell_x1 is None
                    or cell_y0 is None
                    or cell_y1 is None
                ):
                    points = [
                        point
                        for poly in list(cell.get("polygons") or [])
                        for point in self._normalize_grounding_points(poly)
                        if isinstance(point, Mapping)
                    ]
                    xs = [float(point.get("x") or 0.0) for point in points]
                    ys = [float(point.get("y") or 0.0) for point in points]
                    if xs and ys:
                        cell_x0 = min(xs)
                        cell_x1 = max(xs)
                        cell_y0 = min(ys)
                        cell_y1 = max(ys)
                if cell_text:
                    matrix[row_start][col_start] = cell_text
                normalized_cells.append(
                    {
                        "cell_id": int(cell.get("cell_id") or len(normalized_cells)),
                        "row_start": int(row_start),
                        "row_end": int(row_end),
                        "col_start": int(col_start),
                        "col_end": int(max(col_start, int(cell.get("col_end") or col_start))),
                        "rowspan": int(max(1, row_end - row_start + 1)),
                        "colspan": int(max(1, int(max(col_start, int(cell.get("col_end") or col_start))) - col_start + 1)),
                        "text": cell_text,
                        "layout_ids": list(cell.get("layout_ids") or []),
                        "x0": cell_x0,
                        "x1": cell_x1,
                        "y0": cell_y0,
                        "y1": cell_y1,
                        "polygons": list(cell.get("polygons") or []),
                    }
                )
                cell_anchor = _build_cell_anchor(cell=cell)
                if cell_anchor:
                    cell_evidence.append(cell_anchor)
                for row_index in range(row_start, row_end + 1):
                    row_cells_map.setdefault(row_index, [])
                    if cell not in row_cells_map[row_index]:
                        row_cells_map[row_index].append(dict(cell))

            matrix = [row for row in matrix if any(self._normalize_spaces(cell) for cell in row)]

            if normalized_cells and max_col >= 0:
                column_bounds: List[Optional[Tuple[float, float]]] = [None] * (max_col + 1)
                global_x0: Optional[float] = None
                global_x1: Optional[float] = None
                for cell in normalized_cells:
                    x0 = None
                    x1 = None
                    try:
                        x0 = float(cell.get("x0")) if cell.get("x0") is not None else None
                        x1 = float(cell.get("x1")) if cell.get("x1") is not None else None
                    except Exception:
                        x0 = None
                        x1 = None
                    if x0 is None or x1 is None or x1 <= x0:
                        points = [
                            point
                            for poly in list(cell.get("polygons") or [])
                            for point in self._normalize_grounding_points(poly)
                            if isinstance(point, Mapping)
                        ]
                        xs = [float(point.get("x") or 0.0) for point in points]
                        if xs:
                            x0 = min(xs)
                            x1 = max(xs)
                    if x0 is None or x1 is None or x1 <= x0:
                        continue
                    global_x0 = x0 if global_x0 is None else min(global_x0, x0)
                    global_x1 = x1 if global_x1 is None else max(global_x1, x1)
                    col_start = int(cell.get("col_start") or 0)
                    col_end = int(cell.get("col_end") or col_start)
                    span = max(1, col_end - col_start + 1)
                    segment_width = (x1 - x0) / span
                    for offset, column_index in enumerate(range(col_start, col_end + 1)):
                        seg_x0 = x0 + segment_width * offset
                        seg_x1 = x0 + segment_width * (offset + 1)
                        existing = column_bounds[column_index]
                        if existing is None:
                            column_bounds[column_index] = (seg_x0, seg_x1)
                        else:
                            column_bounds[column_index] = (
                                min(existing[0], seg_x0),
                                max(existing[1], seg_x1),
                            )
                if global_x0 is not None and global_x1 is not None and global_x1 > global_x0:
                    total_width = max(1e-6, global_x1 - global_x0)
                    raw_widths: List[float] = []
                    for item in column_bounds:
                        if item is None:
                            raw_widths.append(0.0)
                        else:
                            raw_widths.append(max(0.0, (item[1] - item[0]) / total_width))
                    raw_sum = sum(raw_widths)
                    if raw_sum > 0:
                        column_widths = [value / raw_sum for value in raw_widths]

            def _looks_like_header_row(cells: Sequence[str]) -> bool:
                values = [self._normalize_spaces(cell) for cell in list(cells or []) if self._normalize_spaces(cell)]
                if len(values) < 2:
                    return False
                if max(len(value) for value in values) > 72:
                    return False
                numericish = sum(1 for value in values if re.fullmatch(r"[-+±]?\d+(?:\.\d+)?%?", value))
                if numericish >= max(1, len(values) - 1):
                    return False
                return True

            def _looks_like_data_row(cells: Sequence[str]) -> bool:
                values = [self._normalize_spaces(cell) for cell in list(cells or []) if self._normalize_spaces(cell)]
                if len(values) < 2:
                    return False
                numericish = sum(1 for value in values if re.search(r"\d", value) or "±" in value or "%" in value)
                return numericish >= max(1, len(values) // 2)

            if matrix and _looks_like_header_row(matrix[0]):
                header_row_count = 1
                if len(matrix) >= 3 and _looks_like_header_row(matrix[1]) and _looks_like_data_row(matrix[2]):
                    header_row_count = 2
            for row_index in sorted(row_cells_map.keys()):
                row_anchor = _build_row_anchor(row_index=row_index, row_cells=row_cells_map[row_index])
                if row_anchor:
                    row_evidence.append(row_anchor)

        markdown_matrix: List[List[str]] = []
        saw_markdown_separator = False
        if not matrix:
            for line in markdown_lines:
                pieces = [self._normalize_spaces(cell) for cell in re.split(r"\||\t", line.strip().strip("|"))]
                if not any(pieces):
                    continue
                if all(not cell or re.fullmatch(r":?-{2,}:?", cell) for cell in pieces):
                    saw_markdown_separator = True
                    continue
                markdown_matrix.append(pieces)
        if not matrix and markdown_matrix:
            matrix = markdown_matrix
            header_row_count = 1 if saw_markdown_separator and len(markdown_matrix) >= 2 else 0

        if not matrix and table_blocks:
            sorted_blocks = sorted(table_blocks, key=lambda row: (float(row.get("top") or 0.0), float(row.get("x0") or 0.0)))
            avg_height = sum(max(1.0, float(row.get("bottom") or 0.0) - float(row.get("top") or 0.0)) for row in sorted_blocks) / max(1, len(sorted_blocks))
            row_threshold = max(10.0, avg_height * 0.72)
            clustered_rows: List[List[Dict[str, Any]]] = []
            row_centers: List[float] = []
            for block in sorted_blocks:
                top = float(block.get("top") or 0.0)
                bottom = float(block.get("bottom") or 0.0)
                center_y = (top + bottom) / 2.0
                if clustered_rows and abs(center_y - row_centers[-1]) <= row_threshold:
                    clustered_rows[-1].append(block)
                    merged_centers = [
                        (float(item.get("top") or 0.0) + float(item.get("bottom") or 0.0)) / 2.0
                        for item in clustered_rows[-1]
                    ]
                    row_centers[-1] = sum(merged_centers) / max(1, len(merged_centers))
                else:
                    clustered_rows.append([block])
                    row_centers.append(center_y)
            matrix = [
                [self._normalize_spaces(str(item.get("text") or "")) for item in sorted(row, key=lambda cell: float(cell.get("x0") or 0.0)) if self._normalize_spaces(str(item.get("text") or ""))]
                for row in clustered_rows
            ]
            matrix = [row for row in matrix if row]

            def _looks_like_header_row(cells: Sequence[str]) -> bool:
                values = [self._normalize_spaces(cell) for cell in list(cells or []) if self._normalize_spaces(cell)]
                if len(values) < 2:
                    return False
                if max(len(value) for value in values) > 72:
                    return False
                numericish = sum(1 for value in values if re.fullmatch(r"[-+±]?\d+(?:\.\d+)?%?", value))
                if numericish >= max(1, len(values) - 1):
                    return False
                return True

            def _looks_like_data_row(cells: Sequence[str]) -> bool:
                values = [self._normalize_spaces(cell) for cell in list(cells or []) if self._normalize_spaces(cell)]
                if len(values) < 2:
                    return False
                numericish = sum(1 for value in values if re.search(r"\d", value) or "±" in value or "%" in value)
                return numericish >= max(1, len(values) // 2)

            if matrix and _looks_like_header_row(matrix[0]):
                header_row_count = 1
                if len(matrix) >= 3 and _looks_like_header_row(matrix[1]) and _looks_like_data_row(matrix[2]):
                    header_row_count = 2

        column_count = max((len(row) for row in matrix), default=0)
        matrix = [row + [""] * max(0, column_count - len(row)) for row in matrix]
        header_rows = matrix[:header_row_count] if header_row_count > 0 else []
        body_rows = matrix[header_row_count:] if header_row_count < len(matrix) else matrix

        headers: List[str] = []
        if header_rows:
            for col_index in range(column_count):
                parts = [
                    self._normalize_spaces(row[col_index])
                    for row in header_rows
                    if col_index < len(row) and self._normalize_spaces(row[col_index])
                ]
                headers.append(" / ".join(parts) if parts else f"Column {col_index + 1}")
        elif column_count > 0:
            headers = [f"Column {col_index + 1}" for col_index in range(column_count)]

        rows = [
            {
                f"col_{col_index + 1}": row[col_index] if col_index < len(row) else ""
                for col_index in range(column_count)
            }
            for row in body_rows
        ] if column_count > 0 else []

        logical_rows: List[Dict[str, Any]] = []
        logical_header_row_count = 0
        reconstruction_mode = "deterministic"
        reconstruction_notes: List[str] = []
        if isinstance(logical_row_plan, Mapping) and list(logical_row_plan.get("logical_rows") or []):
            logical_rows, logical_header_row_count = self._materialize_layout_uid_logical_table_rows(
                normalized_cells=normalized_cells,
                logical_row_plan=logical_row_plan,
            )
            reconstruction_mode = "ai_logical_rows"
            reconstruction_notes = [
                str(item).strip()
                for item in list(logical_row_plan.get("notes") or [])
                if str(item).strip()
            ]

        caption = " ".join(text for text in caption_texts if text).strip()
        title = caption or f"Table · Page {int(page)}"
        return {
            "title": title,
            "headers": headers,
            "header_row_count": int(header_row_count),
            "column_widths": column_widths,
            "matrix": matrix,
            "table_cells": normalized_cells,
            "logical_rows": logical_rows,
            "logical_header_row_count": int(logical_header_row_count),
            "rows": rows,
            "caption": caption,
            "notes": note_texts,
            "raw_markdown": raw_markdown,
            "row_evidence": row_evidence,
            "cell_evidence": cell_evidence,
            "reconstruction_mode": reconstruction_mode,
            "reconstruction_notes": reconstruction_notes,
            "ai_insight": "",
        }

    def _build_layout_uid_equation_props(
        self,
        *,
        atoms: Sequence[Mapping[str, Any]],
        equation_refinement: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        clean_texts = [
            self._normalize_spaces(str(atom.get("clean_text") or atom.get("raw_text") or ""))
            for atom in list(atoms or [])
            if isinstance(atom, Mapping)
        ]
        clean_texts = [text for text in clean_texts if text]
        transcript = " ".join(clean_texts).strip() or "x = y"
        merged = transcript
        label = ""
        match = re.match(
            r"^\s*((?:eq(?:uation)?\.?\s*\(?\d+[A-Za-z]?\)?))\s*[:.\-]?\s*(.+)$",
            merged,
            flags=re.IGNORECASE,
        )
        if match:
            label = self._normalize_spaces(str(match.group(1) or ""))
            merged = self._normalize_spaces(str(match.group(2) or "")) or merged
        description = ""
        where_match = re.search(r"\bwhere\b", merged, flags=re.IGNORECASE)
        if where_match and where_match.start() > 0:
            description = self._normalize_spaces(merged[where_match.start() :])
            merged = self._normalize_spaces(merged[: where_match.start()])
        if not label:
            for atom in list(atoms or []):
                if not isinstance(atom, Mapping):
                    continue
                for block in list(atom.get("blocks") or []):
                    if not isinstance(block, Mapping):
                        continue
                    block_text = self._normalize_spaces(str(block.get("text") or ""))
                    if re.fullmatch(r"\(\d+[A-Za-z]?\)", block_text):
                        label = block_text
                        break
                if label:
                    break
        trailing_label = re.search(r"(\(\d+[A-Za-z]?\))\s*$", merged)
        if trailing_label:
            extracted_label = self._normalize_spaces(str(trailing_label.group(1) or ""))
            if extracted_label and not label:
                label = extracted_label
            merged = self._normalize_spaces(merged[: trailing_label.start()])
        latex = merged.replace("−", "-").replace("–", "-").strip()
        normalized_refinement = dict(equation_refinement or {})
        normalized_text = self._normalize_spaces(str(normalized_refinement.get("normalized_text") or ""))
        normalized_latex = str(normalized_refinement.get("normalized_latex") or "").strip()
        normalization_reason = self._normalize_spaces(str(normalized_refinement.get("reason") or ""))
        normalization_mode = self._normalize_spaces(str(normalized_refinement.get("mode") or ""))
        normalization_confidence = 0.0
        try:
            normalization_confidence = max(
                0.0,
                min(1.0, float(normalized_refinement.get("confidence") or 0.0)),
            )
        except Exception:
            normalization_confidence = 0.0
        props = {
            "latex": latex or "x = y",
            "label": label,
            "description": description,
            "render_mode": "math_first" if normalized_latex else "image_first",
            "transcript": transcript,
        }
        if normalized_text:
            props["normalized_text"] = normalized_text
        if normalized_latex:
            props["normalized_latex"] = normalized_latex
        if normalization_reason:
            props["normalization_reason"] = normalization_reason
        if normalization_mode:
            props["normalization_mode"] = normalization_mode
        if normalized_text or normalized_latex:
            props["normalization_confidence"] = float(normalization_confidence)
        return props

    def _build_layout_uid_fallback_group_plan(
        self,
        *,
        grounding: Mapping[str, Any],
    ) -> Dict[str, Any]:
        layout_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
        ]
        layout_atoms = sorted(layout_atoms, key=lambda item: int(item.get("reading_order") or 0))
        groups: List[Dict[str, Any]] = []
        omissions: List[Dict[str, Any]] = []
        index = 0
        while index < len(layout_atoms):
            atom = dict(layout_atoms[index])
            layout_id = str(atom.get("layout_id") or "").strip()
            node_kind = str(atom.get("node_kind") or "").strip().lower() or "paragraph"
            include_in_main_flow = bool(atom.get("include_in_main_flow"))
            if not layout_id:
                index += 1
                continue
            if not include_in_main_flow or node_kind in {"metadata", "doi", "header", "footer", "noise"}:
                omissions.append(
                    {
                        "layout_id": layout_id,
                        "reason": node_kind or "omit",
                    }
                )
                index += 1
                continue
            if node_kind == "figure":
                source_layout_ids = [layout_id]
                lookahead = index + 1
                while lookahead < len(layout_atoms):
                    candidate = dict(layout_atoms[lookahead])
                    candidate_kind = str(candidate.get("node_kind") or "").strip().lower()
                    candidate_id = str(candidate.get("layout_id") or "").strip()
                    if (
                        candidate_kind == "figure_caption"
                        and bool(candidate.get("include_in_main_flow"))
                        and candidate_id
                    ):
                        source_layout_ids.append(candidate_id)
                        lookahead += 1
                        continue
                    break
                groups.append(
                    {
                        "group_id": f"figure_{len(groups) + 1}",
                        "group_kind": "figure",
                        "source_layout_ids": source_layout_ids,
                        "rationale": "deterministic_figure_with_adjacent_caption",
                    }
                )
                index = lookahead
                continue
            if node_kind == "table":
                source_layout_ids = [layout_id]
                lookahead = index + 1
                while lookahead < len(layout_atoms):
                    candidate = dict(layout_atoms[lookahead])
                    candidate_kind = str(candidate.get("node_kind") or "").strip().lower()
                    candidate_id = str(candidate.get("layout_id") or "").strip()
                    if (
                        candidate_kind in {"table", "table_caption"}
                        and bool(candidate.get("include_in_main_flow"))
                        and candidate_id
                    ):
                        source_layout_ids.append(candidate_id)
                        lookahead += 1
                        continue
                    break
                groups.append(
                    {
                        "group_id": f"table_{len(groups) + 1}",
                        "group_kind": "table",
                        "source_layout_ids": source_layout_ids,
                        "rationale": "deterministic_table_with_adjacent_caption",
                    }
                )
                index = lookahead
                continue
            if node_kind == "equation":
                groups.append(
                    {
                        "group_id": f"equation_{len(groups) + 1}",
                        "group_kind": "equation",
                        "source_layout_ids": [layout_id],
                        "rationale": "deterministic_equation_node",
                    }
                )
                index += 1
                continue
            if node_kind == "paragraph":
                source_layout_ids = [layout_id]
                lookahead = index + 1
                while lookahead < len(layout_atoms):
                    candidate = dict(layout_atoms[lookahead])
                    candidate_kind = str(candidate.get("node_kind") or "").strip().lower()
                    candidate_id = str(candidate.get("layout_id") or "").strip()
                    if (
                        candidate_kind == "paragraph"
                        and bool(candidate.get("include_in_main_flow"))
                        and candidate_id
                    ):
                        source_layout_ids.append(candidate_id)
                        lookahead += 1
                        if len(source_layout_ids) >= 3:
                            break
                        continue
                    break
                groups.append(
                    {
                        "group_id": f"paragraph_{len(groups) + 1}",
                        "group_kind": "paragraph",
                        "source_layout_ids": source_layout_ids,
                        "rationale": "deterministic_adjacent_paragraph_merge",
                    }
                )
                index = lookahead
                continue
            if node_kind == "list":
                groups.append(
                    {
                        "group_id": f"list_{len(groups) + 1}",
                        "group_kind": "list",
                        "source_layout_ids": [layout_id],
                        "rationale": "deterministic_list_node",
                    }
                )
                index += 1
                continue
            normalized_kind = node_kind if node_kind in self._layout_uid_group_kinds() else "paragraph"
            groups.append(
                {
                    "group_id": f"{normalized_kind}_{len(groups) + 1}",
                    "group_kind": normalized_kind,
                    "source_layout_ids": [layout_id],
                    "rationale": "deterministic_single_layout_group",
                }
            )
            index += 1

        return {
            "groups": groups,
            "omissions": omissions,
            "notes": ["deterministic_layout_uid_fallback"],
        }

    def _normalize_layout_uid_group_plan(
        self,
        *,
        grounding: Mapping[str, Any],
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        layout_atoms = [
            dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping)
        ]
        layout_index = {
            str(row.get("layout_id") or "").strip(): dict(row)
            for row in layout_atoms
            if str(row.get("layout_id") or "").strip()
        }
        known_ids = set(layout_index.keys())
        used_ids: List[str] = []
        errors: List[str] = []
        normalized_groups: List[Dict[str, Any]] = []
        normalized_omissions: List[Dict[str, Any]] = []

        def _normalize_group_paragraphs(
            raw_rows: Any,
            *,
            source_layout_ids: Sequence[str],
        ) -> List[Dict[str, Any]]:
            if not isinstance(raw_rows, list):
                return []
            allowed_ids = {str(item).strip() for item in list(source_layout_ids or []) if str(item).strip()}
            normalized_rows: List[Dict[str, Any]] = []
            for raw_row in raw_rows:
                if isinstance(raw_row, Mapping):
                    text = self._normalize_spaces(str(raw_row.get("text") or ""))
                    raw_para_layout_ids = list(raw_row.get("source_layout_ids") or [])
                else:
                    text = self._normalize_spaces(str(raw_row or ""))
                    raw_para_layout_ids = []
                if not text:
                    continue
                paragraph_row: Dict[str, Any] = {"text": text}
                paragraph_layout_ids = [
                    str(item).strip()
                    for item in raw_para_layout_ids
                    if str(item).strip() and str(item).strip() in allowed_ids
                ]
                if paragraph_layout_ids:
                    paragraph_row["source_layout_ids"] = list(dict.fromkeys(paragraph_layout_ids))
                normalized_rows.append(paragraph_row)
            return normalized_rows

        for raw_group in list((step_result or {}).get("groups") or []):
            if not isinstance(raw_group, Mapping):
                continue
            raw_source_layout_ids = [
                str(item).strip()
                for item in list(
                    raw_group.get("source_layout_ids")
                    or raw_group.get("layout_ids")
                    or raw_group.get("target_layout_ids")
                    or []
                )
                if str(item).strip()
            ]
            duplicate_ids = sorted({layout_id for layout_id in raw_source_layout_ids if raw_source_layout_ids.count(layout_id) > 1})
            if duplicate_ids:
                errors.extend([f"duplicate_layout_id:{layout_id}" for layout_id in duplicate_ids])
            source_layout_ids = list(dict.fromkeys(raw_source_layout_ids))
            if not source_layout_ids:
                continue
            unknown_ids = [layout_id for layout_id in source_layout_ids if layout_id not in known_ids]
            if unknown_ids:
                errors.extend([f"unknown_layout_id:{layout_id}" for layout_id in unknown_ids])
                continue
            group_kind = str(raw_group.get("group_kind") or raw_group.get("kind") or "").strip().lower()
            if group_kind not in self._layout_uid_group_kinds():
                first_atom = layout_index.get(source_layout_ids[0]) or {}
                group_kind = str(first_atom.get("node_kind") or "").strip().lower() or "paragraph"
            omit_from_main_flow = bool(raw_group.get("omit_from_main_flow"))
            if group_kind in {"metadata", "doi", "header", "footer", "noise"} or omit_from_main_flow:
                for layout_id in source_layout_ids:
                    normalized_omissions.append(
                        {
                            "layout_id": layout_id,
                            "reason": str(raw_group.get("reason") or group_kind or "omit").strip() or "omit",
                        }
                    )
                    used_ids.append(layout_id)
                continue
            normalized_group = {
                "group_id": str(raw_group.get("group_id") or f"group_{len(normalized_groups) + 1}").strip()
                or f"group_{len(normalized_groups) + 1}",
                "group_kind": group_kind,
                "source_layout_ids": source_layout_ids,
                "rationale": str(raw_group.get("rationale") or raw_group.get("reason") or "").strip(),
            }
            if group_kind in {"paragraph", "table_caption"}:
                paragraphs = _normalize_group_paragraphs(
                    raw_group.get("paragraphs"),
                    source_layout_ids=source_layout_ids,
                )
                if paragraphs:
                    normalized_group["paragraphs"] = paragraphs
            normalized_groups.append(normalized_group)
            used_ids.extend(source_layout_ids)

        for raw_omission in list((step_result or {}).get("omissions") or []):
            if not isinstance(raw_omission, Mapping):
                continue
            layout_id = str(raw_omission.get("layout_id") or "").strip()
            if not layout_id:
                continue
            if layout_id not in known_ids:
                errors.append(f"unknown_layout_id:{layout_id}")
                continue
            normalized_omissions.append(
                {
                    "layout_id": layout_id,
                    "reason": str(raw_omission.get("reason") or "omit").strip() or "omit",
                }
            )
            used_ids.append(layout_id)

        duplicates = sorted({layout_id for layout_id in used_ids if used_ids.count(layout_id) > 1})
        if duplicates:
            errors.extend([f"duplicate_layout_id:{layout_id}" for layout_id in duplicates])
        missing = [layout_id for layout_id in layout_index if layout_id not in set(used_ids)]
        if missing:
            errors.extend([f"missing_layout_id:{layout_id}" for layout_id in missing])

        if errors or not normalized_groups:
            fallback_plan = self._build_layout_uid_fallback_group_plan(grounding=grounding)
            return fallback_plan, {
                "passed": False,
                "errors": errors or ["empty_groups"],
                "fallback_used": True,
            }

        normalized_groups = sorted(
            normalized_groups,
            key=lambda row: min(
                int((layout_index.get(layout_id) or {}).get("reading_order") or 10**9)
                for layout_id in list(row.get("source_layout_ids") or [])
            ),
        )
        normalized_omissions = list(
            {
                f"{str(row.get('layout_id') or '').strip()}::{str(row.get('reason') or '').strip()}": dict(row)
                for row in normalized_omissions
                if str(row.get("layout_id") or "").strip()
            }.values()
        )
        return {
            "groups": normalized_groups,
            "omissions": normalized_omissions,
            "notes": [
                str(item).strip()
                for item in list((step_result or {}).get("notes") or [])
                if str(item).strip()
            ],
        }, {
            "passed": True,
            "errors": [],
            "fallback_used": False,
        }

    def _normalize_layout_uid_page_decision(
        self,
        *,
        step_result: Mapping[str, Any],
    ) -> Dict[str, Any]:
        raw_decision = step_result.get("page_decision") if isinstance(step_result, Mapping) else {}
        if not isinstance(raw_decision, Mapping):
            raw_decision = {}
        legacy_reconstruction = step_result.get("reconstruction") if isinstance(step_result, Mapping) else {}
        if not isinstance(legacy_reconstruction, Mapping):
            legacy_reconstruction = {}
        mode = self._normalize_spaces(
            str(raw_decision.get("mode") or legacy_reconstruction.get("mode") or "")
        ).strip().lower()
        if mode in {"ai_reconstructed", "ai_only", "ungrounded"}:
            mode = "fully_reconstructed"
        if mode not in {"grounded", "partial_reconstructed", "fully_reconstructed"}:
            mode = "grounded"
        reason = self._normalize_spaces(
            str(
                raw_decision.get("reason")
                or raw_decision.get("rationale")
                or legacy_reconstruction.get("reason")
                or ""
            )
        )
        try:
            confidence = max(
                0.0,
                min(
                    1.0,
                    float(raw_decision.get("confidence") or legacy_reconstruction.get("confidence") or 0.0),
                ),
            )
        except Exception:
            confidence = 0.0
        return {
            "mode": mode,
            "reason": reason,
            "confidence": confidence,
        }

    def _normalize_layout_uid_reconstructed_component_items(
        self,
        *,
        raw_components: Any,
    ) -> Tuple[List[Dict[str, Any]], List[str]]:
        allowed_kinds = self._layout_uid_ai_reconstruction_component_kinds()
        normalized_components: List[Dict[str, Any]] = []
        errors: List[str] = []

        def _normalize_component_bbox_norm(raw_value: Any) -> Optional[Dict[str, float]]:
            bbox = self._normalize_bbox_norm(raw_value)
            if bbox:
                return bbox
            if isinstance(raw_value, Mapping):
                visual_spec = raw_value.get("visual_spec")
                if isinstance(visual_spec, Mapping):
                    bbox = self._normalize_bbox_norm(
                        visual_spec.get("bbox_norm")
                        or visual_spec.get("seed_bbox_norm")
                        or visual_spec.get("bbox")
                    )
                    if bbox:
                        return bbox
            return None

        def _normalize_paragraph_rows(value: Any) -> List[Dict[str, Any]]:
            rows: List[Dict[str, Any]] = []
            for item in list(value or [])[:24]:
                if isinstance(item, Mapping):
                    text = self._normalize_spaces(str(item.get("text") or item.get("content") or ""))
                    bbox_norm = _normalize_component_bbox_norm(item.get("bbox_norm") or item.get("bbox"))
                else:
                    text = self._normalize_spaces(str(item or ""))
                    bbox_norm = None
                if text:
                    paragraph_row: Dict[str, Any] = {"text": text}
                    if bbox_norm:
                        paragraph_row["bbox_norm"] = bbox_norm
                    rows.append(paragraph_row)
            return rows

        def _normalize_visual_spec(raw_spec: Any) -> Dict[str, Any]:
            spec = dict(raw_spec or {}) if isinstance(raw_spec, Mapping) else {}
            normalized: Dict[str, Any] = {
                "target_kind": "figure",
                "require_full_boundary": bool(spec.get("require_full_boundary", True)),
                "prefer_without_caption": bool(spec.get("prefer_without_caption", True)),
                "allow_caption_if_needed": bool(spec.get("allow_caption_if_needed", False)),
            }
            seed_bbox_norm = self._normalize_bbox_norm(
                spec.get("seed_bbox_norm")
                or spec.get("bbox_norm")
                or spec.get("bbox")
            )
            if seed_bbox_norm:
                normalized["seed_bbox_norm"] = seed_bbox_norm
            must_include = [
                self._normalize_spaces(str(item or ""))
                for item in list(spec.get("must_include") or [])[:8]
                if self._normalize_spaces(str(item or ""))
            ]
            if must_include:
                normalized["must_include"] = must_include
            must_exclude = [
                self._normalize_spaces(str(item or ""))
                for item in list(spec.get("must_exclude") or [])[:8]
                if self._normalize_spaces(str(item or ""))
            ]
            if must_exclude:
                normalized["must_exclude"] = must_exclude
            region_description = self._normalize_spaces(
                str(
                    spec.get("region_description")
                    or spec.get("visual_description")
                    or spec.get("crop_description")
                    or ""
                )
            )
            if region_description:
                normalized["region_description"] = region_description
            boundary_notes = self._normalize_spaces(str(spec.get("boundary_notes") or spec.get("notes") or ""))
            if boundary_notes:
                normalized["boundary_notes"] = boundary_notes
            crop_strategy = self._normalize_spaces(str(spec.get("crop_strategy") or spec.get("caption_policy") or ""))
            if crop_strategy:
                normalized["crop_strategy"] = crop_strategy
            return normalized

        if isinstance(raw_components, Mapping):
            component_rows = list(raw_components.get("components") or raw_components.get("items") or [])
        else:
            component_rows = list(raw_components or [])

        for idx, raw_component in enumerate(component_rows[:20], start=1):
            if not isinstance(raw_component, Mapping):
                continue
            kind = str(raw_component.get("kind") or raw_component.get("type") or raw_component.get("component") or "").strip().lower()
            if kind not in allowed_kinds:
                errors.append(f"unsupported_reconstruction_component:{kind or idx}")
                continue
            component_bbox_norm = _normalize_component_bbox_norm(raw_component.get("bbox_norm") or raw_component.get("bbox"))
            if kind == "heading":
                text = self._normalize_spaces(str(raw_component.get("text") or raw_component.get("title") or ""))
                if not text:
                    errors.append(f"reconstruction_heading_missing_text:{idx}")
                    continue
                normalized_component = {
                    "kind": "heading",
                    "text": text,
                    "level": max(1, min(4, int(raw_component.get("level") or 2))),
                }
                if component_bbox_norm:
                    normalized_component["bbox_norm"] = component_bbox_norm
                normalized_components.append(normalized_component)
                continue
            if kind == "paragraph":
                paragraphs = _normalize_paragraph_rows(raw_component.get("paragraphs"))
                text = self._normalize_spaces(str(raw_component.get("text") or raw_component.get("content") or ""))
                if not text and paragraphs:
                    text = "\n\n".join(str(row.get("text") or "").strip() for row in paragraphs if str(row.get("text") or "").strip())
                if not text:
                    errors.append(f"reconstruction_paragraph_missing_text:{idx}")
                    continue
                normalized_component = {
                    "kind": "paragraph",
                    "text": text,
                    "paragraphs": paragraphs,
                }
                if component_bbox_norm:
                    normalized_component["bbox_norm"] = component_bbox_norm
                else:
                    row_bboxes = [
                        _normalize_component_bbox_norm(row.get("bbox_norm"))
                        for row in paragraphs
                        if isinstance(row, Mapping)
                    ]
                    row_bboxes = [row for row in row_bboxes if isinstance(row, dict)]
                    if row_bboxes:
                        merged_bbox = self._bbox_norm_union(row_bboxes)
                        if merged_bbox:
                            normalized_component["bbox_norm"] = merged_bbox
                normalized_components.append(normalized_component)
                continue
            if kind == "list":
                items = [
                    self._normalize_spaces(str(item or ""))
                    for item in list(raw_component.get("items") or raw_component.get("bullets") or [])[:20]
                    if self._normalize_spaces(str(item or ""))
                ]
                if not items:
                    errors.append(f"reconstruction_list_missing_items:{idx}")
                    continue
                normalized_component = {"kind": "list", "items": items}
                if component_bbox_norm:
                    normalized_component["bbox_norm"] = component_bbox_norm
                normalized_components.append(normalized_component)
                continue
            if kind == "figure":
                caption = self._normalize_spaces(str(raw_component.get("caption") or raw_component.get("text") or ""))
                raw_notes = raw_component.get("notes")
                if not isinstance(raw_notes, list):
                    raw_notes = raw_component.get("reconstruction_notes")
                notes = [
                    self._normalize_spaces(str(item or ""))
                    for item in list(raw_notes or [])[:12]
                    if self._normalize_spaces(str(item or ""))
                ]
                partial_reconstruction_raw = raw_component.get("partial_reconstruction")
                if isinstance(partial_reconstruction_raw, str):
                    partial_reconstruction: Any = self._normalize_spaces(partial_reconstruction_raw)
                else:
                    partial_reconstruction = bool(partial_reconstruction_raw) if partial_reconstruction_raw is not None else False
                normalized_component = {
                    "kind": "figure",
                    "caption": caption,
                    "source_label": self._normalize_spaces(str(raw_component.get("source_label") or raw_component.get("label") or "")),
                    "visual_spec": _normalize_visual_spec(
                        raw_component.get("visual_spec")
                        or raw_component.get("image_spec")
                        or raw_component.get("crop_spec")
                    ),
                }
                if notes:
                    normalized_component["notes"] = notes
                    normalized_component["reconstruction_notes"] = notes
                if partial_reconstruction:
                    normalized_component["partial_reconstruction"] = partial_reconstruction
                if component_bbox_norm:
                    normalized_component["bbox_norm"] = component_bbox_norm
                normalized_components.append(normalized_component)
                continue
            if kind == "table":
                headers = [
                    self._normalize_spaces(str(item or ""))
                    for item in list(raw_component.get("headers") or [])[:24]
                    if self._normalize_spaces(str(item or ""))
                ]
                row_matrix: List[List[str]] = []
                for row in list(raw_component.get("rows") or [])[:40]:
                    if isinstance(row, Mapping):
                        ordered_values = [self._normalize_spaces(str(value or "")) for value in list(row.values())]
                        row_values = [value for value in ordered_values if value]
                    else:
                        row_values = [
                            self._normalize_spaces(str(item or ""))
                            for item in list(row or [])[:24]
                            if self._normalize_spaces(str(item or ""))
                        ]
                    if row_values:
                        row_matrix.append(row_values)
                normalized_component = {
                    "kind": "table",
                    "title": self._normalize_spaces(str(raw_component.get("title") or "")),
                    "caption": self._normalize_spaces(str(raw_component.get("caption") or "")),
                    "headers": headers,
                    "rows": row_matrix,
                    "raw_markdown": str(raw_component.get("raw_markdown") or "").strip(),
                }
                if component_bbox_norm:
                    normalized_component["bbox_norm"] = component_bbox_norm
                normalized_components.append(normalized_component)
                continue
            if kind == "equation":
                latex = str(raw_component.get("latex") or "").strip()
                transcript = self._normalize_spaces(str(raw_component.get("transcript") or raw_component.get("text") or latex))
                if not latex and not transcript:
                    errors.append(f"reconstruction_equation_missing_text:{idx}")
                    continue
                normalized_component = {
                    "kind": "equation",
                    "latex": latex,
                    "transcript": transcript,
                    "label": self._normalize_spaces(str(raw_component.get("label") or "")),
                    "description": self._normalize_spaces(str(raw_component.get("description") or "")),
                }
                if component_bbox_norm:
                    normalized_component["bbox_norm"] = component_bbox_norm
                normalized_components.append(normalized_component)

        return normalized_components, errors

    def _normalize_layout_uid_reconstructed_components(
        self,
        *,
        step_result: Mapping[str, Any],
        page_decision: Mapping[str, Any],
    ) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
        mode = self._normalize_spaces(str((page_decision or {}).get("mode") or "")).strip().lower()
        if mode not in {"partial_reconstructed", "fully_reconstructed"}:
            return [], {
                "enabled": False,
                "passed": True,
                "errors": [],
            }

        raw_components: Any = []
        if isinstance(step_result, Mapping):
            raw_components = step_result.get("reconstructed_components") or []
            if not raw_components:
                legacy_reconstruction = step_result.get("reconstruction")
                if isinstance(legacy_reconstruction, Mapping):
                    raw_components = legacy_reconstruction.get("components") or legacy_reconstruction.get("items") or []

        legacy_reconstruction = step_result.get("reconstruction") if isinstance(step_result, Mapping) else {}
        if not isinstance(legacy_reconstruction, Mapping):
            legacy_reconstruction = {}
        reconstruction_payload = {
            "reconstruction": {
                "mode": mode,
                "docmind_quality": str(legacy_reconstruction.get("docmind_quality") or legacy_reconstruction.get("quality") or "").strip(),
                "reason": self._normalize_spaces(str((page_decision or {}).get("reason") or legacy_reconstruction.get("reason") or "")),
                "confidence": self._safe_float(
                    (page_decision or {}).get("confidence"),
                    self._safe_float(legacy_reconstruction.get("confidence"), 0.0),
                ),
                "components": raw_components,
                "notes": [
                    self._normalize_spaces(str(item or ""))
                    for item in list(legacy_reconstruction.get("notes") or [])
                    if self._normalize_spaces(str(item or ""))
                ],
            }
        }
        normalized_plan, normalized_validation = self._normalize_layout_uid_ai_reconstruction_plan(
            step_result=reconstruction_payload,
        )
        normalized_components = [
            dict(row)
            for row in list(normalized_plan.get("components") or [])
            if isinstance(row, Mapping)
        ]
        errors = [str(item).strip() for item in list(normalized_validation.get("errors") or []) if str(item).strip()]
        if not normalized_components:
            errors.append("empty_reconstructed_components")
        return normalized_components, {
            "enabled": bool(normalized_validation.get("enabled")) and bool(normalized_components),
            "passed": not errors,
            "errors": errors,
        }

    def _normalize_layout_uid_ai_reconstruction_plan(
        self,
        *,
        step_result: Mapping[str, Any],
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        raw_plan = step_result.get("reconstruction") if isinstance(step_result, Mapping) else {}
        if not isinstance(raw_plan, Mapping):
            return {
                "mode": "grounded",
                "docmind_quality": "",
                "reason": "",
                "confidence": 0.0,
                "components": [],
                "notes": [],
            }, {
                "enabled": False,
                "passed": True,
                "errors": [],
            }

        mode = str(raw_plan.get("mode") or "").strip().lower()
        if mode in {"ai_only", "ungrounded"}:
            mode = "ai_reconstructed"
        if mode == "ai_reconstructed":
            mode = "fully_reconstructed"
        quality = str(raw_plan.get("docmind_quality") or raw_plan.get("quality") or "").strip().lower()
        quality_gate = quality in {"poor", "bad", "broken", "low", "unusable"}
        enabled = mode in {"partial_reconstructed", "fully_reconstructed"} and (
            quality_gate or mode in {"partial_reconstructed", "fully_reconstructed"}
        )
        if not enabled:
            return {
                "mode": "grounded",
                "docmind_quality": quality,
                "reason": str(raw_plan.get("reason") or "").strip(),
                "confidence": float(raw_plan.get("confidence") or 0.0) if str(raw_plan.get("confidence") or "").strip() else 0.0,
                "components": [],
                "notes": [str(item).strip() for item in list(raw_plan.get("notes") or []) if str(item).strip()],
            }, {
                "enabled": False,
                "passed": True,
                "errors": [],
            }

        normalized_components, errors = self._normalize_layout_uid_reconstructed_component_items(
            raw_components=raw_plan.get("components") or raw_plan.get("items") or [],
        )
        confidence = 0.0
        try:
            confidence = max(0.0, min(1.0, float(raw_plan.get("confidence") or 0.0)))
        except Exception:
            errors.append("invalid_reconstruction_confidence")

        if not normalized_components:
            errors.append("empty_reconstruction_components")

        return {
            "mode": mode if mode in {"partial_reconstructed", "fully_reconstructed"} else "fully_reconstructed",
            "docmind_quality": quality or "poor",
            "reason": self._normalize_spaces(str(raw_plan.get("reason") or "")),
            "confidence": confidence,
            "components": normalized_components,
            "notes": [str(item).strip() for item in list(raw_plan.get("notes") or []) if str(item).strip()],
        }, {
            "enabled": not errors,
            "passed": not errors,
            "errors": errors,
        }

    def _normalize_layout_uid_combined_plan(
        self,
        *,
        grounding: Mapping[str, Any],
        step_result: Mapping[str, Any],
    ) -> Dict[str, Any]:
        normalization_plan, text_validation = self._normalize_layout_uid_sparse_text_normalization_plan(
            grounding=grounding,
            step_result=step_result,
        )
        grouping_plan, grouping_validation = self._normalize_layout_uid_group_plan(
            grounding=grounding,
            step_result=step_result,
        )
        page_decision = self._normalize_layout_uid_page_decision(step_result=step_result)
        reconstructed_components, reconstructed_validation = self._normalize_layout_uid_reconstructed_components(
            step_result=step_result,
            page_decision=page_decision,
        )
        reconstruction_plan, reconstruction_validation = self._normalize_layout_uid_ai_reconstruction_plan(
            step_result=step_result,
        )
        decision_mode = str(page_decision.get("mode") or "").strip().lower()
        if decision_mode == "fully_reconstructed" and list(reconstructed_components or []):
            confidence = self._safe_float(page_decision.get("confidence"), self._safe_float(reconstruction_plan.get("confidence"), 0.0))
            reconstruction_plan = {
                "mode": "ai_reconstructed",
                "docmind_quality": str(reconstruction_plan.get("docmind_quality") or "poor").strip() or "poor",
                "reason": str(page_decision.get("reason") or reconstruction_plan.get("reason") or "").strip(),
                "confidence": confidence,
                "components": list(reconstructed_components or []),
                "notes": list(reconstruction_plan.get("notes") or []),
            }
            reconstruction_validation = {
                "enabled": bool(reconstructed_validation.get("enabled")),
                "passed": bool(reconstructed_validation.get("passed")),
                "errors": [str(item).strip() for item in list(reconstructed_validation.get("errors") or []) if str(item).strip()],
            }
        elif decision_mode in {"grounded", "partial_reconstructed"}:
            reconstruction_plan = {
                "mode": "grounded",
                "docmind_quality": str(reconstruction_plan.get("docmind_quality") or "").strip(),
                "reason": str(page_decision.get("reason") or reconstruction_plan.get("reason") or "").strip(),
                "confidence": self._safe_float(page_decision.get("confidence"), 0.0),
                "components": list(reconstructed_components or []) if decision_mode == "partial_reconstructed" else [],
                "notes": list(reconstruction_plan.get("notes") or []),
            }
            reconstruction_validation = {
                "enabled": False,
                "passed": True,
                "errors": [],
            }
        return {
            "normalization_plan": normalization_plan,
            "text_validation": text_validation,
            "grouping_plan": grouping_plan,
            "grouping_validation": grouping_validation,
            "page_decision": page_decision,
            "reconstructed_components": reconstructed_components,
            "reconstructed_validation": reconstructed_validation,
            "reconstruction_plan": reconstruction_plan,
            "reconstruction_validation": reconstruction_validation,
        }

    async def _build_layout_uid_table_refinement_map(
        self,
        *,
        page: int,
        grouping_plan: Mapping[str, Any],
        grounding: Mapping[str, Any],
        rendered_page_image: str,
        rendered_page_image_path: str,
    ) -> Dict[str, Dict[str, Any]]:
        refinement_map: Dict[str, Dict[str, Any]] = {}
        if not (rendered_page_image or rendered_page_image_path):
            return refinement_map
        layout_index = {
            str(row.get("layout_id") or "").strip(): dict(row)
            for row in list((grounding or {}).get("layout_atoms") or [])
            if isinstance(row, Mapping) and str(row.get("layout_id") or "").strip()
        }
        for raw_group in list((grouping_plan or {}).get("groups") or []):
            if not isinstance(raw_group, Mapping):
                continue
            if str(raw_group.get("group_kind") or "").strip().lower() != "table":
                continue
            group_id = str(raw_group.get("group_id") or "").strip()
            source_layout_ids = [
                str(item).strip()
                for item in list(raw_group.get("source_layout_ids") or [])
                if str(item).strip() and str(item).strip() in layout_index
            ]
            if not group_id or not source_layout_ids:
                continue
            atoms = [layout_index[layout_id] for layout_id in source_layout_ids if layout_id in layout_index]
            draft_table_props = self._build_layout_uid_table_props(page=page, atoms=atoms)
            table_cells = [
                dict(row)
                for row in list(draft_table_props.get("table_cells") or [])
                if isinstance(row, Mapping)
            ]
            physical_rows = self._build_layout_uid_table_physical_rows(table_cells)
            if len(physical_rows) < 3:
                continue
            prompt_payload = self._build_layout_uid_table_logical_row_prompt_payload(
                page=page,
                title=str(draft_table_props.get("title") or ""),
                caption=str(draft_table_props.get("caption") or ""),
                table_cells=table_cells,
            )
            model_result = await self._invoke_single_agent_model(
                system_prompt=self._layout_uid_table_logical_row_system_prompt(),
                user_prompt=prompt_payload,
                rendered_page_image=rendered_page_image,
                rendered_page_image_path=rendered_page_image_path,
                step=2,
                phase=f"layout_uid_table_logical_rows:{group_id}",
            )
            normalized_plan, validation = self._normalize_layout_uid_table_logical_row_plan(
                physical_rows=physical_rows,
                step_result=dict(model_result.get("step_result") or {}),
            )
            refinement_map[group_id] = {
                "logical_row_plan": normalized_plan,
                "validation": validation,
                "usage": dict(model_result.get("usage") or {}),
                "model_status": str(model_result.get("status") or "").strip().lower() or "done",
            }
        return refinement_map

